import math

def clamp(lo, hi, x):
    return max(lo, min(hi, x))

def srgb_to_linear(c):
    if c <= 0.04045:
        return c / 12.92
    return ((c + 0.055) / 1.055) ** 2.4

def linear_to_srgb(c):
    if c <= 0.0031308:
        return 12.92 * c
    return 1.055 * (c ** (1/2.4)) - 0.055

def rgb_to_hsl(r, g, b):
    # r,g,b in 0..1
    mx = max(r, g, b); mn = min(r, g, b)
    l = (mx + mn) / 2
    if mx == mn:
        h = 0.0; s = 0.0
    else:
        d = mx - mn
        s = d / (1 - abs(2*l - 1))
        if mx == r:
            h = 60 * (((g - b) / d) % 6)
        elif mx == g:
            h = 60 * ((b - r) / d + 2)
        else:
            h = 60 * ((r - g) / d + 4)
    return h, s, l

def hsl_to_rgb(h, s, l):
    h = h % 360
    c = (1 - abs(2*l - 1)) * s
    hp = h / 60
    x = c * (1 - abs(hp % 2 - 1))
    if hp < 1: r,g,b = c,x,0
    elif hp < 2: r,g,b = x,c,0
    elif hp < 3: r,g,b = 0,c,x
    elif hp < 4: r,g,b = 0,x,c
    elif hp < 5: r,g,b = x,0,c
    else: r,g,b = c,0,x
    m = l - c/2
    return r+m, g+m, b+m

def rgb_to_xyz(r, g, b):
    rl, gl, bl = srgb_to_linear(r), srgb_to_linear(g), srgb_to_linear(b)
    X = 0.4124*rl + 0.3576*gl + 0.1805*bl
    Y = 0.2126*rl + 0.7152*gl + 0.0722*bl
    Z = 0.0193*rl + 0.1192*gl + 0.9505*bl
    return X, Y, Z

def xyz_to_rgb(X, Y, Z):
    rl =  3.2406*X - 1.5372*Y - 0.4986*Z
    gl = -0.9689*X + 1.8758*Y + 0.0415*Z
    bl =  0.0557*X - 0.2040*Y + 1.0570*Z
    return linear_to_srgb(rl), linear_to_srgb(gl), linear_to_srgb(bl)

XN, YN, ZN = 0.95047, 1.0, 1.08883
def xyz_to_lab(X, Y, Z):
    def f(t):
        return t ** (1/3) if t > (6/29)**3 else t/(3*(6/29)**2) + 4/29
    fx, fy, fz = f(X/XN), f(Y/YN), f(Z/ZN)
    return 116*fy - 16, 500*(fx - fy), 200*(fy - fz)

def lab_to_xyz(L, a, b):
    def finv(t):
        return t**3 if t > 6/29 else 3*(6/29)**2*(t - 4/29)
    fy = (L + 16) / 116
    fx = a / 500 + fy
    fz = fy - b / 200
    return XN*finv(fx), YN*finv(fy), ZN*finv(fz)

def lab_to_lch(L, a, b):
    c = math.hypot(a, b)
    h = math.degrees(math.atan2(b, a)) % 360
    return L, c, h

def lch_to_lab(L, c, h):
    return L, c*math.cos(math.radians(h)), c*math.sin(math.radians(h))

def rgb_to_lab(r, g, b):
    return xyz_to_lab(*rgb_to_xyz(r, g, b))

def lab_to_rgb(L, a, b):
    return xyz_to_rgb(*lab_to_xyz(L, a, b))

def rgb_to_oklab(r, g, b):
