//! Core color type and color space conversions.
#![allow(dead_code)]

use std::fmt::Write as _;

pub type Scalar = f64;

/// clamp(lower, upper, x) with NaN mapping to `upper`
pub fn clamp(lower: Scalar, upper: Scalar, x: Scalar) -> Scalar {
    Scalar::max(lower, Scalar::min(upper, x))
}

pub fn mod_positive(x: Scalar, y: Scalar) -> Scalar {
    (x % y + y) % y
}

pub fn interpolate(a: Scalar, b: Scalar, fraction: Scalar) -> Scalar {
    a + fraction * (b - a)
}

pub fn interpolate_angle(a: Scalar, b: Scalar, fraction: Scalar) -> Scalar {
    let paths = [(a, b), (a, b + 360.0), (a + 360.0, b)];
    let dist = |p: &(Scalar, Scalar)| (p.0 - p.1).abs();
    let mut best = &paths[0];
    for p in &paths[1..] {
        if dist(p) < dist(best) {
            best = p;
        }
    }
    mod_positive(interpolate(best.0, best.1, fraction), 360.0)
}

#[derive(Debug, Clone, Copy, PartialEq)]
