}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LCh {
    pub l: Scalar,
    pub c: Scalar,
    pub h: Scalar,
    pub alpha: Scalar,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct OkLab {
    pub l: Scalar,
    pub a: Scalar,
    pub b: Scalar,
    pub alpha: Scalar,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct OkLCh {
    pub l: Scalar,
    pub c: Scalar,
    pub h: Scalar,
    pub alpha: Scalar,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct CMYK {
    pub c: Scalar,
    pub m: Scalar,
    pub y: Scalar,
    pub k: Scalar,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Color {
    pub hue: Scalar,
    pub saturation: Scalar,
    pub lightness: Scalar,
    pub alpha: Scalar,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Format {
    Spaces,
    NoSpaces,
}

impl Format {
    fn sep(self) -> &'static str {
        match self {
            Format::Spaces => ", ",
            Format::NoSpaces => ",",
        }
    }
}

/// Rust-like `f64 as u8` saturating conversion.
pub fn f64_to_u8(x: Scalar) -> u8 {
    if x.is_nan() {
        0
    } else if x <= 0.0 {
        0
    } else if x >= 255.0 {
        255
    } else {
        x as u8
    }
}

fn normalize_hue(h: Scalar) -> Scalar {
    if h.is_finite() {
        mod_positive(h, 360.0)
    } else {
        Scalar::NAN
    }
}

impl Color {
    pub fn from_hsla(hue: Scalar, saturation: Scalar, lightness: Scalar, alpha: Scalar) -> Color {
        Color {
            hue: normalize_hue(hue),
            saturation: clamp(0.0, 1.0, saturation),
            lightness: clamp(0.0, 1.0, lightness),
            alpha: clamp(0.0, 1.0, alpha),
        }
    }

    pub fn from_hsl(hue: Scalar, saturation: Scalar, lightness: Scalar) -> Color {
        Color::from_hsla(hue, saturation, lightness, 1.0)
    }

    pub fn from_hsva(hue: Scalar, s: Scalar, v: Scalar, alpha: Scalar) -> Color {
        let l = v * (1.0 - s / 2.0);
        let sl = if l == 0.0 || l == 1.0 {
            0.0
        } else {
            (v - l) / Scalar::min(l, 1.0 - l)
        };
        Color::from_hsla(hue, sl, l, alpha)
    }

    pub fn from_rgba(r: u8, g: u8, b: u8, alpha: Scalar) -> Color {
        let r = Scalar::from(r) / 255.0;
        let g = Scalar::from(g) / 255.0;
        let b = Scalar::from(b) / 255.0;
        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let chroma = max - min;
        let hue = 60.0
            * if chroma == 0.0 {
                0.0
            } else if r == max {
                mod_positive((g - b) / chroma, 6.0)
            } else if g == max {
                (b - r) / chroma + 2.0
            } else {
                (r - g) / chroma + 4.0
            };
        let lightness = (max + min) / 2.0;
        let saturation = if chroma == 0.0 {
            0.0
        } else {
            chroma / (1.0 - Scalar::abs(2.0 * lightness - 1.0))
        };
        Color::from_hsla(hue, saturation, lightness, alpha)
    }

    pub fn from_rgb(r: u8, g: u8, b: u8) -> Color {
        Color::from_rgba(r, g, b, 1.0)
    }

    /// Floating point RGB (0..1) values get quantized to 8 bit first.
    pub fn from_rgba_float(r: Scalar, g: Scalar, b: Scalar, alpha: Scalar) -> Color {
        let q = |c: Scalar| -> u8 { f64_to_u8(Scalar::round(clamp(0.0, 255.0, c * 255.0))) };
        Color::from_rgba(q(r), q(g), q(b), alpha)
    }

    pub fn from_rgb_float(r: Scalar, g: Scalar, b: Scalar) -> Color {
        Color::from_rgba_float(r, g, b, 1.0)
    }

    pub fn from_xyz(x: Scalar, y: Scalar, z: Scalar, alpha: Scalar) -> Color {
        let r = 3.2406 * x - 1.5372 * y - 0.4986 * z;
        let g = -0.9689 * x + 1.8758 * y + 0.0415 * z;
        let b = 0.0557 * x - 0.2040 * y + 1.0570 * z;
        Color::from_rgba_float(linear_to_srgb(r), linear_to_srgb(g), linear_to_srgb(b), alpha)
    }

    pub fn from_lms(l: Scalar, m: Scalar, s: Scalar, alpha: Scalar) -> Color {
        let x = 1.91020 * l - 1.11212 * m + 0.20191 * s;
        let y = 0.37095 * l + 0.62905 * m + 0.0 * s;
        let z = s;
        Color::from_xyz(x, y, z, alpha)
    }

    pub fn from_lab(l: Scalar, a: Scalar, b: Scalar, alpha: Scalar) -> Color {
        const DELTA: Scalar = 6.0 / 29.0;
        let finv = |t: Scalar| -> Scalar {
            if t > DELTA {
                t * t * t
            } else {
                3.0 * DELTA * DELTA * (t - 4.0 / 29.0)
            }
        };
        let l_ = (l + 16.0) / 116.0;
        let x = D65_XN * finv(l_ + a / 500.0);
        let y = D65_YN * finv(l_);
        let z = D65_ZN * finv(l_ - b / 200.0);
        Color::from_xyz(x, y, z, alpha)
    }

    pub fn from_lch(l: Scalar, c: Scalar, h: Scalar, alpha: Scalar) -> Color {
        let hr = h.to_radians();
        Color::from_lab(l, c * hr.cos(), c * hr.sin(), alpha)
    }

    pub fn from_oklab(l: Scalar, a: Scalar, b: Scalar, alpha: Scalar) -> Color {
        let l_ = 0.9999999985 * l + 0.3963377922 * a + 0.2158037581 * b;
        let m_ = 1.0000000089 * l - 0.1055613423 * a - 0.0638541748 * b;
        let s_ = 1.0000000547 * l - 0.0894841821 * a - 1.2914855379 * b;
        let ll = l_ * l_ * l_;
        let mm = m_ * m_ * m_;
        let ss = s_ * s_ * s_;
        let x = 1.2270138511 * ll - 0.5577999807 * mm + 0.2812561490 * ss;
        let y = -0.0405801784 * ll + 1.1122568696 * mm - 0.0716766787 * ss;
        let z = -0.0763812845 * ll - 0.4214819784 * mm + 1.5861632204 * ss;
        Color::from_xyz(x, y, z, alpha)
    }

    pub fn from_oklch(l: Scalar, c: Scalar, h: Scalar, alpha: Scalar) -> Color {
        let hr = h.to_radians();
        Color::from_oklab(l, c * hr.cos(), c * hr.sin(), alpha)
    }

    pub fn graytone(lightness: Scalar) -> Color {
        Color::from_hsl(0.0, 0.0, lightness)
    }

    pub fn black() -> Color {
        Color::from_hsl(0.0, 0.0, 0.0)
    }
    pub fn white() -> Color {
        Color::from_hsl(0.0, 0.0, 1.0)
    }
    pub fn red() -> Color {
        Color::from_rgb(255, 0, 0)
    }
    pub fn green() -> Color {
        Color::from_rgb(0, 128, 0)
    }
    pub fn blue() -> Color {
        Color::from_rgb(0, 0, 255)
    }
    pub fn yellow() -> Color {
        Color::from_rgb(255, 255, 0)
    }

    pub fn to_hsla(&self) -> HSLA {
        HSLA {
            h: self.hue,
            s: self.saturation,
            l: self.lightness,
            alpha: self.alpha,
        }
    }

    pub fn to_hsva(&self) -> HSVA {
        let l = self.lightness;
        let v = l + self.saturation * Scalar::min(l, 1.0 - l);
        let s = if v == 0.0 { 0.0 } else { 2.0 * (1.0 - l / v) };
        HSVA {
            h: self.hue,
            s,
            v,
            alpha: self.alpha,
        }
    }

    pub fn to_rgba_float(&self) -> RGBA<Scalar> {
        let h_s = self.hue / 60.0;
        let chr = (1.0 - Scalar::abs(2.0 * self.lightness - 1.0)) * self.saturation;
        let m = self.lightness - chr / 2.0;
        let x = chr * (1.0 - Scalar::abs(h_s % 2.0 - 1.0));
        let (r_, g_, b_) = if h_s < 1.0 {
            (chr, x, 0.0)
        } else if (1.0..2.0).contains(&h_s) {
            (x, chr, 0.0)
        } else if (2.0..3.0).contains(&h_s) {
            (0.0, chr, x)
        } else if (3.0..4.0).contains(&h_s) {
            (0.0, x, chr)
        } else if (4.0..5.0).contains(&h_s) {
            (x, 0.0, chr)
        } else {
            (chr, 0.0, x)
        };
        RGBA {
            r: r_ + m,
            g: g_ + m,
            b: b_ + m,
            alpha: self.alpha,
        }
    }

    pub fn to_rgba(&self) -> RGBA<u8> {
        let c = self.to_rgba_float();
        RGBA {
            r: f64_to_u8(Scalar::round(c.r * 255.0)),
            g: f64_to_u8(Scalar::round(c.g * 255.0)),
            b: f64_to_u8(Scalar::round(c.b * 255.0)),
            alpha: self.alpha,
        }
    }

    pub fn to_xyz(&self) -> XYZ {
        let c = self.to_rgba_float();
        let r = srgb_to_linear(c.r);
        let g = srgb_to_linear(c.g);
        let b = srgb_to_linear(c.b);
        XYZ {
            x: 0.4124 * r + 0.3576 * g + 0.1805 * b,
            y: 0.2126 * r + 0.7152 * g + 0.0722 * b,
            z: 0.0193 * r + 0.1192 * g + 0.9505 * b,
            alpha: self.alpha,
        }
    }

    pub fn to_lms(&self) -> LMS {
        let xyz = self.to_xyz();
        LMS {
            l: 0.38971 * xyz.x + 0.68898 * xyz.y - 0.07868 * xyz.z,
            m: -0.22981 * xyz.x + 1.18340 * xyz.y + 0.04641 * xyz.z,
            s: xyz.z,
            alpha: self.alpha,
        }
    }

    pub fn to_lab(&self) -> Lab {
        let xyz = self.to_xyz();
        const CUT: Scalar = (6.0 / 29.0) * (6.0 / 29.0) * (6.0 / 29.0);
        let f = |t: Scalar| -> Scalar {
            if t > CUT {
                t.cbrt()
            } else {
                t / (3.0 * (6.0 / 29.0) * (6.0 / 29.0)) + 4.0 / 29.0
            }
        };
        let fx = f(xyz.x / D65_XN);
        let fy = f(xyz.y / D65_YN);
        let fz = f(xyz.z / D65_ZN);
        Lab {
            l: 116.0 * fy - 16.0,
            a: 500.0 * (fx - fy),
            b: 200.0 * (fy - fz),
            alpha: self.alpha,
        }
    }

    pub fn to_lch(&self) -> LCh {
        let lab = self.to_lab();
        LCh {
            l: lab.l,
            c: Scalar::sqrt(lab.a * lab.a + lab.b * lab.b),
            h: mod_positive(lab.b.atan2(lab.a).to_degrees(), 360.0),
            alpha: self.alpha,
        }
    }

    pub fn to_oklab(&self) -> OkLab {
        let xyz = self.to_xyz();
        let l = 0.8189330101 * xyz.x + 0.3618667424 * xyz.y - 0.1288597137 * xyz.z;
        let m = 0.0329845436 * xyz.x + 0.9293118715 * xyz.y + 0.0361456387 * xyz.z;
        let s = 0.0482003018 * xyz.x + 0.2643662691 * xyz.y + 0.6338517070 * xyz.z;
        let l_ = l.cbrt();
        let m_ = m.cbrt();
        let s_ = s.cbrt();
        OkLab {
            l: 0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_,
            a: 1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_,
            b: 0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_,
            alpha: self.alpha,
        }
    }

    pub fn to_oklch(&self) -> OkLCh {
        let lab = self.to_oklab();
        OkLCh {
            l: lab.l,
            c: Scalar::sqrt(lab.a * lab.a + lab.b * lab.b),
            h: mod_positive(lab.b.atan2(lab.a).to_degrees(), 360.0),
            alpha: self.alpha,
        }
    }

    pub fn to_cmyk(&self) -> CMYK {
        let c = self.to_rgba_float();
        let k = 1.0 - c.r.max(c.g).max(c.b);
        if k == 1.0 {
            CMYK {
                c: 0.0,
                m: 0.0,
                y: 0.0,
                k,
            }
        } else {
            CMYK {
                c: (1.0 - c.r - k) / (1.0 - k),
                m: (1.0 - c.g - k) / (1.0 - k),
                y: (1.0 - c.b - k) / (1.0 - k),
                k,
            }
        }
    }

    pub fn luminance(&self) -> Scalar {
        self.to_xyz().y
    }

    pub fn brightness(&self) -> Scalar {
        let c = self.to_rgba_float();
        0.299 * c.r + 0.587 * c.g + 0.114 * c.b
    }

    pub fn is_light(&self) -> bool {
        self.brightness() > 0.5
    }

    pub fn text_color(&self) -> Color {
        if self.luminance() > 0.179 {
            Color::black()
        } else {
            Color::white()
        }
    }

    pub fn to_gray(&self) -> Color {
        let y = self.luminance();
        let gray = Color::from_rgb_float(linear_to_srgb(y), linear_to_srgb(y), linear_to_srgb(y));
        Color::from_hsl(self.hue, 0.0, gray.lightness)
    }

    pub fn rotate_hue(&self, delta: Scalar) -> Color {
        Color::from_hsla(self.hue + delta, self.saturation, self.lightness, self.alpha)
    }

    pub fn complementary(&self) -> Color {
        self.rotate_hue(180.0)
    }

    pub fn lighten(&self, f: Scalar) -> Color {
        Color::from_hsla(self.hue, self.saturation, self.lightness + f, self.alpha)
    }

    pub fn darken(&self, f: Scalar) -> Color {
        self.lighten(-f)
    }

    pub fn saturate(&self, f: Scalar) -> Color {
        Color::from_hsla(self.hue, self.saturation + f, self.lightness, self.alpha)
    }

    pub fn desaturate(&self, f: Scalar) -> Color {
        self.saturate(-f)
    }

    pub fn with_alpha(&self, alpha: Scalar) -> Color {
        Color::from_hsla(self.hue, self.saturation, self.lightness, alpha)
    }

    pub fn mix(&self, other: &Color, fraction: Scalar, space: ColorSpace) -> Color {
        match space {
            ColorSpace::Rgb => {
                let a = self.to_rgba_float();
                let b = other.to_rgba_float();
                Color::from_rgba_float(
                    interpolate(a.r, b.r, fraction),
                    interpolate(a.g, b.g, fraction),
                    interpolate(a.b, b.b, fraction),
                    interpolate(a.alpha, b.alpha, fraction),
                )
            }
            ColorSpace::Hsl => {
                let a = self.to_hsla();
                let b = other.to_hsla();
                let ha = if a.s < 0.0001 { b.h } else { a.h };
                let hb = if b.s < 0.0001 { a.h } else { b.h };
                Color::from_hsla(
                    interpolate_angle(ha, hb, fraction),
                    interpolate(a.s, b.s, fraction),
                    interpolate(a.l, b.l, fraction),
                    interpolate(a.alpha, b.alpha, fraction),
                )
            }
            ColorSpace::Lab => {
                let a = self.to_lab();
                let b = other.to_lab();
                Color::from_lab(
                    interpolate(a.l, b.l, fraction),
                    interpolate(a.a, b.a, fraction),
                    interpolate(a.b, b.b, fraction),
                    interpolate(a.alpha, b.alpha, fraction),
                )
            }
            ColorSpace::LCh => {
                let a = self.to_lch();
                let b = other.to_lch();
                let ha = if a.c < 0.1 { b.h } else { a.h };
                let hb = if b.c < 0.1 { a.h } else { b.h };
                Color::from_lch(
                    interpolate(a.l, b.l, fraction),
                    interpolate(a.c, b.c, fraction),
                    interpolate_angle(ha, hb, fraction),
                    interpolate(a.alpha, b.alpha, fraction),
                )
            }
            ColorSpace::OkLab => {
                let a = self.to_oklab();
                let b = other.to_oklab();
                Color::from_oklab(
                    interpolate(a.l, b.l, fraction),
                    interpolate(a.a, b.a, fraction),
                    interpolate(a.b, b.b, fraction),
                    interpolate(a.alpha, b.alpha, fraction),
                )
            }
        }
    }

    /// Composite `self` (with alpha) over `background` (sRGB space, truncating).
    pub fn composited(&self, background: &Color) -> Color {
        let fg = self.to_rgba();
        let bg = background.to_rgba();
        let a = self.alpha;
        let blend = |f: u8, b: u8| -> u8 {
            f64_to_u8((Scalar::from(f) * a + Scalar::from(b) * (1.0 - a)).floor())
        };
        Color::from_rgb(blend(fg.r, bg.r), blend(fg.g, bg.g), blend(fg.b, bg.b))
    }

    pub fn distance_delta_e_cie76(&self, other: &Color) -> Scalar {
        let a = self.to_lab();
        let b = other.to_lab();
        delta_e_cie76(&a, &b)
    }

    pub fn distance_delta_e_ciede2000(&self, other: &Color) -> Scalar {
        let a = self.to_lab();
        let b = other.to_lab();
        delta_e_ciede2000(&a, &b)
    }

    pub fn simulate_colorblindness(&self, kind: ColorblindnessType) -> Color {
        let lms = self.to_lms();
        let (l, m, s) = match kind {
            ColorblindnessType::Protanopia => (1.05118294 * lms.m - 0.05116099 * lms.s, lms.m, lms.s),
            ColorblindnessType::Deuteranopia => (lms.l, 0.9513092 * lms.l + 0.04866992 * lms.s, lms.s),
            ColorblindnessType::Tritanopia => (lms.l, lms.m, -0.86744736 * lms.l + 1.86727089 * lms.m),
        };
        Color::from_lms(l, m, s, self.alpha)
    }

    // ----- formatting -----

    pub fn to_rgb_string(&self, format: Format) -> String {
        let c = self.to_rgba();
        if self.alpha == 1.0 {
            format!("rgb({}{s}{}{s}{})", c.r, c.g, c.b, s = format.sep())
        } else {
            format!(
                "rgba({}{s}{}{s}{}{s}{})",
                c.r,
                c.g,
                c.b,
                format_alpha(self.alpha),
                s = format.sep()
            )
        }
    }

    pub fn to_rgb_float_string(&self, format: Format) -> String {
        let c = self.to_rgba_float();
        if self.alpha == 1.0 {
            format!("rgb({:.3}{s}{:.3}{s}{:.3})", c.r, c.g, c.b, s = format.sep())
        } else {
            format!(
                "rgba({:.3}{s}{:.3}{s}{:.3}{s}{})",
                c.r,
                c.g,
                c.b,
                format_alpha(self.alpha),
                s = format.sep()
            )
        }
    }

    pub fn to_rgb_hex_string(&self, leading_hash: bool) -> String {
        let c = self.to_rgba();
        let mut s = String::new();
        if leading_hash {
            s.push('#');
        }
        let _ = write!(s, "{:02x}{:02x}{:02x}", c.r, c.g, c.b);
        if self.alpha != 1.0 {
            let a = f64_to_u8(Scalar::round(self.alpha * 255.0));
            let _ = write!(s, "{:02x}", a);
        }
        s
    }

    pub fn to_hsl_string(&self, format: Format) -> String {
        let h = self.to_hsla();
        if self.alpha == 1.0 {
            format!(
                "hsl({:.0}{s}{:.1}%{s}{:.1}%)",
                h.h,
                100.0 * h.s,
                100.0 * h.l,
                s = format.sep()
            )
        } else {
            format!(
                "hsla({:.0}{s}{:.1}%{s}{:.1}%{s}{})",
                h.h,
                100.0 * h.s,
                100.0 * h.l,
                format_alpha(self.alpha),
                s = format.sep()
            )
        }
    }

    pub fn to_hsv_string(&self, format: Format) -> String {
        let h = self.to_hsva();
        if self.alpha == 1.0 {
            format!(
                "hsv({:.0}{s}{:.1}%{s}{:.1}%)",
                h.h,
                100.0 * h.s,
                100.0 * h.v,
                s = format.sep()
            )
        } else {
            format!(
                "hsva({:.0}{s}{:.1}%{s}{:.1}%{s}{})",
                h.h,
                100.0 * h.s,
                100.0 * h.v,
                format_alpha(self.alpha),
                s = format.sep()
            )
        }
    }

    pub fn to_lab_string(&self, format: Format) -> String {
        let l = self.to_lab();
        if self.alpha == 1.0 {
            format!("Lab({:.0}{s}{:.0}{s}{:.0})", l.l, l.a, l.b, s = format.sep())
        } else {
            format!(
                "Lab({:.0}{s}{:.0}{s}{:.0}{s}{})",
                l.l,
                l.a,
                l.b,
                format_alpha(self.alpha),
                s = format.sep()
            )
        }
    }

    pub fn to_lch_string(&self, format: Format) -> String {
        let l = self.to_lch();
        if self.alpha == 1.0 {
            format!("LCh({:.0}{s}{:.0}{s}{:.0})", l.l, l.c, l.h, s = format.sep())
        } else {
            format!(
                "LCh({:.0}{s}{:.0}{s}{:.0}{s}{})",
                l.l,
                l.c,
                l.h,
                format_alpha(self.alpha),
                s = format.sep()
            )
        }
    }

    pub fn to_oklab_string(&self, format: Format) -> String {
        let l = self.to_oklab();
        if self.alpha == 1.0 {
            format!("OkLab({:.4}{s}{:.4}{s}{:.4})", l.l, l.a, l.b, s = format.sep())
        } else {
            format!(
                "OkLab({:.4}{s}{:.4}{s}{:.4}{s}{})",
                l.l,
                l.a,
                l.b,
                format_alpha(self.alpha),
                s = format.sep()
            )
        }
    }

    pub fn to_oklch_string(&self, format: Format) -> String {
        let l = self.to_oklch();
        if self.alpha == 1.0 {
            format!("OkLCh({:.4}{s}{:.4}{s}{:.4})", l.l, l.c, l.h, s = format.sep())
        } else {
            format!(
                "OkLCh({:.4}{s}{:.4}{s}{:.4}{s}{})",
                l.l,
                l.c,
                l.h,
                format_alpha(self.alpha),
                s = format.sep()
            )
        }
    }

    pub fn to_cmyk_string(&self, format: Format) -> String {
        let c = self.to_cmyk();
        format!(
            "cmyk({:.0}{s}{:.0}{s}{:.0}{s}{:.0})",
            c.c * 100.0,
            c.m * 100.0,
            c.y * 100.0,
            c.k * 100.0,
            s = format.sep()
        )
    }
}

pub fn format_alpha(alpha: Scalar) -> String {
    let a = (alpha * 1000.0).round() / 1000.0;
    format!("{}", a)
}

pub const D65_XN: Scalar = 0.95047;
pub const D65_YN: Scalar = 1.0;
pub const D65_ZN: Scalar = 1.08883;

pub fn srgb_to_linear(c: Scalar) -> Scalar {
    if c <= 0.04045 {
        c / 12.92
    } else {
        Scalar::powf((c + 0.055) / 1.055, 2.4)
    }
}

pub fn linear_to_srgb(c: Scalar) -> Scalar {
    if c <= 0.0031308 {
        12.92 * c
    } else {
        1.055 * Scalar::powf(c, 1.0 / 2.4) - 0.055
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ColorSpace {
    Rgb,
    Hsl,
    Lab,
    LCh,
    OkLab,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ColorblindnessType {
    Protanopia,
    Deuteranopia,
    Tritanopia,
}

pub fn delta_e_cie76(a: &Lab, b: &Lab) -> Scalar {
    let dl = a.l - b.l;
    let da = a.a - b.a;
    let db = a.b - b.b;
    Scalar::sqrt(dl * dl + da * da + db * db)
}

pub fn delta_e_ciede2000(lab1: &Lab, lab2: &Lab) -> Scalar {
    let (l1, a1, b1) = (lab1.l, lab1.a, lab1.b);
    let (l2, a2, b2) = (lab2.l, lab2.a, lab2.b);
    let c1 = (a1 * a1 + b1 * b1).sqrt();
    let c2 = (a2 * a2 + b2 * b2).sqrt();
    let cbar = (c1 + c2) / 2.0;
    let cbar7 = cbar.powi(7);
    let g = 0.5 * (1.0 - (cbar7 / (cbar7 + 25.0f64.powi(7))).sqrt());
    let a1p = (1.0 + g) * a1;
    let a2p = (1.0 + g) * a2;
    let c1p = (a1p * a1p + b1 * b1).sqrt();
    let c2p = (a2p * a2p + b2 * b2).sqrt();
    let hp = |a: Scalar, b: Scalar| -> Scalar {
        if a == 0.0 && b == 0.0 {
            0.0
        } else {
            let h = b.atan2(a).to_degrees();
            if h < 0.0 {
                h + 360.0
            } else {
                h
            }
        }
    };
    let h1p = hp(a1p, b1);
    let h2p = hp(a2p, b2);
    let dlp = l2 - l1;
    let dcp = c2p - c1p;
    let dhp = if c1p * c2p == 0.0 {
        0.0
    } else if (h2p - h1p).abs() <= 180.0 {
        h2p - h1p
    } else if h2p - h1p > 180.0 {
        h2p - h1p - 360.0
    } else {
        h2p - h1p + 360.0
    };
    let dhp_big = 2.0 * (c1p * c2p).sqrt() * (dhp / 2.0).to_radians().sin();
    let lbp = (l1 + l2) / 2.0;
    let cbp = (c1p + c2p) / 2.0;
    let hbp = if c1p * c2p == 0.0 {
        h1p + h2p
    } else if (h1p - h2p).abs() <= 180.0 {
        (h1p + h2p) / 2.0
    } else if h1p + h2p < 360.0 {
        (h1p + h2p + 360.0) / 2.0
    } else {
        (h1p + h2p - 360.0) / 2.0
    };
    let t = 1.0 - 0.17 * (hbp - 30.0).to_radians().cos()
        + 0.24 * (2.0 * hbp).to_radians().cos()
        + 0.32 * (3.0 * hbp + 6.0).to_radians().cos()
        - 0.20 * (4.0 * hbp - 63.0).to_radians().cos();
    let dtheta = 30.0 * Scalar::exp(-((hbp - 275.0) / 25.0).powi(2));
    let cbp7 = cbp.powi(7);
    let rc = 2.0 * (cbp7 / (cbp7 + 25.0f64.powi(7))).sqrt();
    let sl = 1.0 + 0.015 * (lbp - 50.0).powi(2) / (20.0 + (lbp - 50.0).powi(2)).sqrt();
    let sc = 1.0 + 0.045 * cbp;
    let sh = 1.0 + 0.015 * cbp * t;
    let rt = -(2.0 * dtheta).to_radians().sin() * rc;
    Scalar::sqrt(
        (dlp / sl).powi(2) + (dcp / sc).powi(2) + (dhp_big / sh).powi(2) + rt * (dcp / sc) * (dhp_big / sh),
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DistanceMetric {
    CIE76,
    CIEDE2000,
}

pub fn distance(metric: DistanceMetric, a: &Color, b: &Color) -> Scalar {
    match metric {
        DistanceMetric::CIE76 => a.distance_delta_e_cie76(b),
        DistanceMetric::CIEDE2000 => a.distance_delta_e_ciede2000(b),
    }
}
