//! Parsing of color strings (hex, rgb(), hsl(), named colors, ...).

use crate::color::Color;
use crate::named::NAMED_COLORS;

struct Cur<'a> {
    s: &'a str,
    pos: usize,
}

impl<'a> Cur<'a> {
    fn new(s: &'a str) -> Self {
        Cur { s, pos: 0 }
    }
    fn rest(&self) -> &'a str {
        &self.s[self.pos..]
    }
    fn at_end(&self) -> bool {
        self.pos >= self.s.len()
    }
    fn peek(&self) -> Option<char> {
        self.rest().chars().next()
    }
    fn tag(&mut self, t: &str) -> bool {
        if self.rest().starts_with(t) {
            self.pos += t.len();
            true
        } else {
            false
        }
    }
    fn tag_no_case(&mut self, t: &str) -> bool {
        let r = self.rest();
        if r.len() >= t.len() && r.is_char_boundary(t.len()) && r[..t.len()].eq_ignore_ascii_case(t) {
            self.pos += t.len();
            true
        } else {
            false
        }
    }
    /// skip whitespace, return number of chars skipped
    fn ws(&mut self) -> usize {
        let mut n = 0;
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.pos += c.len_utf8();
                n += 1;
            } else {
                break;
            }
        }
        n
    }
    fn digits(&mut self) -> bool {
        let mut n = 0;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                self.pos += 1;
                n += 1;
            } else {
                break;
            }
        }
        n > 0
    }
    /// nom-style `double`
    fn double(&mut self) -> Option<f64> {
        let start = self.pos;
        // recognize_float
        let save = self.pos;
        let mut ok = true;
        if let Some(c) = self.peek() {
            if c == '+' || c == '-' {
                self.pos += 1;
            }
        }
        if self.digits() {
            if self.peek() == Some('.') {
                self.pos += 1;
                self.digits();
            }
        } else if self.peek() == Some('.') {
            self.pos += 1;
            if !self.digits() {
                ok = false;
            }
        } else {
            ok = false;
        }
        if ok {
            if let Some(c) = self.peek() {
                if c == 'e' || c == 'E' {
                    self.pos += 1;
                    if let Some(c2) = self.peek() {
                        if c2 == '+' || c2 == '-' {
                            self.pos += 1;
                        }
                    }
                    if !self.digits() {
                        // cut: hard failure
                        return None;
                    }
                }
            }
            return self.s[start..self.pos].parse::<f64>().ok();
        }
        self.pos = save;
        if self.tag_no_case("nan") {
            return Some(f64::NAN);
        }
        if self.tag_no_case("inf") {
            return Some(f64::INFINITY);
        }
        None
    }
    fn percentage(&mut self) -> Option<f64> {
        let save = self.pos;
        if let Some(v) = self.double() {
            if self.tag("%") {
                return Some(v / 100.0);
            }
        }
        self.pos = save;
        None
    }
    fn number_or_percentage(&mut self) -> Option<f64> {
        let save = self.pos;
        if let Some(v) = self.percentage() {
            return Some(v);
        }
        self.pos = save;
        self.double()
    }
    fn angle(&mut self) -> Option<f64> {
        let v = self.double()?;
        if self.tag("deg") {
            Some(v)
        } else if self.tag("grad") {
            Some(v * 0.9)
        } else if self.tag("rad") {
            Some(v.to_degrees())
        } else if self.tag("turn") {
            Some(v * 360.0)
        } else {
            Some(v)
        }
    }
    /// separator: ws* ',' ws*  |  ws+
    fn sep(&mut self) -> bool {
        let n = self.ws();
        if self.peek() == Some(',') {
            self.pos += 1;
            self.ws();
            true
        } else {
            n > 0
        }
    }
    fn opt_alpha(&mut self) -> Option<f64> {
        let save = self.pos;
        if self.sep() {
            if let Some(a) = self.number_or_percentage() {
                return Some(a);
            }
        }
        self.pos = save;
        None
    }
    fn close(&mut self) -> bool {
        self.ws();
        self.tag(")") && self.at_end()
    }
}

fn parse_hex(s: &str) -> Option<Color> {
    let s = s.strip_prefix('#').unwrap_or(s);
    if !s.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    let v = |i: usize| -> u8 { u8::from_str_radix(&s[i..i + 1], 16).unwrap() };
    let v2 = |i: usize| -> u8 { u8::from_str_radix(&s[i..i + 2], 16).unwrap() };
    match s.len() {
        3 => Some(Color::from_rgb(v(0) * 17, v(1) * 17, v(2) * 17)),
        4 => Some(Color::from_rgba(
            v(0) * 17,
            v(1) * 17,
            v(2) * 17,
            f64::from(v(3) * 17) / 255.0,
        )),
        6 => Some(Color::from_rgb(v2(0), v2(2), v2(4))),
        8 => Some(Color::from_rgba(v2(0), v2(2), v2(4), f64::from(v2(6)) / 255.0)),
        _ => None,
    }
}

fn three_values(c: &mut Cur) -> Option<(f64, f64, f64, bool)> {
    // try three percentages
    let save = c.pos;
    if let Some(a) = c.percentage() {
        if c.sep() {
            if let Some(b) = c.percentage() {
                if c.sep() {
                    if let Some(d) = c.percentage() {
                        return Some((a, b, d, true));
                    }
                }
            }
        }
    }
    c.pos = save;
    let a = c.double()?;
    if !c.sep() {
        return None;
    }
    let b = c.double()?;
    if !c.sep() {
        return None;
    }
    let d = c.double()?;
    Some((a, b, d, false))
}

fn rgb_from_values(v: (f64, f64, f64, bool), alpha: f64) -> Color {
    let (r, g, b, pct) = v;
    if pct {
        Color::from_rgba_float(r, g, b, alpha)
    } else {
        Color::from_rgba_float(r / 255.0, g / 255.0, b / 255.0, alpha)
    }
}

fn parse_rgb(s: &str) -> Option<Color> {
    let mut c = Cur::new(s);
    if !(c.tag("rgba(") || c.tag("rgb(")) {
        return None;
    }
    c.ws();
    let v = three_values(&mut c)?;
    let alpha = c.opt_alpha().unwrap_or(1.0);
    if !c.close() {
        return None;
    }
    Some(rgb_from_values(v, alpha))
}

fn parse_bare_rgb(s: &str) -> Option<Color> {
    let mut c = Cur::new(s);
    let v = three_values(&mut c)?;
    let alpha = c.opt_alpha().unwrap_or(1.0);
    if !c.at_end() {
        return None;
    }
    Some(rgb_from_values(v, alpha))
}

fn parse_hsl_like(s: &str, hsv: bool) -> Option<Color> {
    let mut c = Cur::new(s);
    let ok = if hsv {
        c.tag("hsva(") || c.tag("hsv(")
    } else {
        c.tag("hsla(") || c.tag("hsl(")
    };
    if !ok {
        return None;
    }
    c.ws();
    let h = c.angle()?;
    if !c.sep() {
        return None;
    }
    let sat = c.percentage()?;
    if !c.sep() {
        return None;
    }
    let l = c.percentage()?;
    let alpha = c.opt_alpha().unwrap_or(1.0);
    if !c.close() {
        return None;
    }
    if hsv {
        Some(Color::from_hsva(h, sat, l, alpha))
    } else {
        Some(Color::from_hsla(h, sat, l, alpha))
    }
}

fn parse_gray(s: &str) -> Option<Color> {
    let mut c = Cur::new(s);
    if !c.tag("gray(") {
        return None;
    }
    c.ws();
    let v = c.number_or_percentage()?;
    if !(v >= 0.0) {
        return None;
    }
    if !c.close() {
        return None;
    }
    Some(Color::from_rgba_float(v, v, v, 1.0))
}

fn parse_lab_like(s: &str, names: &[&str], angle_last: bool) -> Option<(f64, f64, f64, f64)> {
    let mut c = Cur::new(s);
    let mut matched = false;
    for n in names {
        if c.tag_no_case(n) {
            matched = true;
            break;
        }
    }
    if !matched {
        return None;
    }
    c.ws();
    let a = c.double()?;
    if !c.sep() {
        return None;
    }
    let b = c.double()?;
    if !c.sep() {
        return None;
    }
    let d = if angle_last { c.angle()? } else { c.double()? };
    let alpha = c.opt_alpha().unwrap_or(1.0);
    if !c.close() {
        return None;
    }
    Some((a, b, d, alpha))
}

fn parse_named(s: &str) -> Option<Color> {
    let lower = s.to_ascii_lowercase();
    NAMED_COLORS
        .iter()
        .find(|nc| nc.name == lower)
        .map(|nc| Color::from_rgb(nc.rgb.0, nc.rgb.1, nc.rgb.2))
}

pub fn parse_color(input: &str) -> Option<Color> {
    let s = input.trim();
    if let Some(c) = parse_hex(s) {
        return Some(c);
    }
    if let Some(c) = parse_rgb(s) {
        return Some(c);
    }
