//! ANSI escape sequence handling.
#![allow(dead_code)]

use crate::color::Color;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Mode {
    Ansi8Bit,
    TrueColor,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Brush {
    mode: Option<Mode>,
}

impl Brush {
    pub fn from_mode(mode: Option<Mode>) -> Brush {
        Brush { mode }
    }

    pub fn mode(&self) -> Option<Mode> {
        self.mode
    }

    pub fn paint(&self, text: &str, style: &Style) -> String {
        match self.mode {
            None => text.to_string(),
            Some(mode) => {
                let mut codes: Vec<String> = Vec::new();
                if let Some(fg) = &style.foreground {
                    codes.push(color_code(fg, mode, false));
                }
                if let Some(bg) = &style.background {
                    codes.push(color_code(bg, mode, true));
                }
                if style.bold {
                    codes.push("1".into());
                }
                if style.italic {
                    codes.push("3".into());
                }
                if style.underline {
                    codes.push("4".into());
                }
                if codes.is_empty() {
                    text.to_string()
                } else {
                    format!("\x1b[{}m{}\x1b[0m", codes.join(";"), text)
                }
            }
        }
    }
}

fn color_code(color: &Color, mode: Mode, background: bool) -> String {
    let prefix = if background { 48 } else { 38 };
    match mode {
        Mode::TrueColor => {
            let c = color.to_rgba();
            format!("{};2;{};{};{}", prefix, c.r, c.g, c.b)
        }
        Mode::Ansi8Bit => format!("{};5;{}", prefix, to_ansi_8bit(color)),
    }
}

#[derive(Debug, Clone, Default)]
pub struct Style {
    pub foreground: Option<Color>,
    pub background: Option<Color>,
    pub bold: bool,
    pub italic: bool,
    pub underline: bool,
}

impl Style {
    pub fn new() -> Style {
        Style::default()
    }
    pub fn foreground(mut self, c: &Color) -> Style {
        self.foreground = Some(*c);
        self
    }
    pub fn on(mut self, c: &Color) -> Style {
        self.background = Some(*c);
        self
    }
    pub fn bold(mut self, b: bool) -> Style {
        self.bold = b;
        self
    }
    pub fn italic(mut self, b: bool) -> Style {
        self.italic = b;
        self
    }
    pub fn underline(mut self, b: bool) -> Style {
        self.underline = b;
        self
    }
}

/// Style for showing a color: text in a readable color on the color's background.
pub fn color_style(color: &Color) -> Style {
    Style::new().foreground(&color.text_color()).on(color)
}

pub fn ansi_8bit_to_color(code: u8) -> Color {
    match code {
        0 => Color::from_rgb(0, 0, 0),
        1 => Color::from_rgb(128, 0, 0),
        2 => Color::from_rgb(0, 128, 0),
        3 => Color::from_rgb(128, 128, 0),
        4 => Color::from_rgb(0, 0, 128),
        5 => Color::from_rgb(128, 0, 128),
        6 => Color::from_rgb(0, 128, 128),
        7 => Color::from_rgb(192, 192, 192),
        8 => Color::from_rgb(128, 128, 128),
        9 => Color::from_rgb(255, 0, 0),
        10 => Color::from_rgb(0, 255, 0),
        11 => Color::from_rgb(255, 255, 0),
        12 => Color::from_rgb(0, 0, 255),
        13 => Color::from_rgb(255, 0, 255),
        14 => Color::from_rgb(0, 255, 255),
        15 => Color::from_rgb(255, 255, 255),
        16..=231 => {
            let c = code - 16;
            let level = |i: u8| -> u8 { if i == 0 { 0 } else { 55 + 40 * i } };
            Color::from_rgb(level(c / 36), level((c % 36) / 6), level(c % 6))
        }
        _ => {
            let v = 8 + 10 * (code - 232);
            Color::from_rgb(v, v, v)
        }
    }
}

/// Approximate a color by the closest 8-bit ANSI color (codes 16..255).
pub fn to_ansi_8bit(color: &Color) -> u8 {
    let lab = color.to_lab();
    let mut best_code = 16u8;
    let mut best_dist = i64::MAX;
    for code in 16u8..255 {
        let other = ansi_8bit_to_color(code).to_lab();
        let d = crate::color::delta_e_ciede2000(&lab, &other) as i64;
        if d < best_dist {
            best_dist = d;
            best_code = code;
        }
    }
    best_code
}

pub fn ansi_escape_8bit(color: &Color) -> String {
    format!("\x1b[38;5;{}m", to_ansi_8bit(color))
}

pub fn ansi_escape_24bit(color: &Color) -> String {
    let c = color.to_rgba();
    format!("\x1b[38;2;{};{};{}m", c.r, c.g, c.b)
}
