//! A simple pixel canvas rendered with unicode half blocks.

use crate::ansi::{Brush, Style};
use crate::color::Color;
use std::io::Write;

pub struct Canvas {
    height: usize,
    width: usize,
    pixels: Vec<Option<Color>>,
    chars: Vec<Option<char>>,
    brush: Brush,
}

impl Canvas {
    /// `height` is given in pixels (two pixels per text row), `width` in columns.
    pub fn new(height: usize, width: usize, brush: Brush) -> Canvas {
        Canvas {
            height,
            width,
            pixels: vec![None; height * width],
            chars: vec![None; (height / 2) * width],
            brush,
        }
    }

    fn idx(&self, row: usize, col: usize) -> usize {
        row * self.width + col
    }

    pub fn draw_rect(&mut self, row: usize, col: usize, height: usize, width: usize, color: &Color) {
        for i in 0..height {
            for j in 0..width {
                let r = row + i;
                let c = col + j;
                if r >= self.height || c >= self.width {
                    continue;
                }
                let idx = self.idx(r, c);
                let new = if color.alpha < 1.0 {
                    match self.pixels[idx] {
                        Some(bg) => color.composited(&bg),
                        None => *color,
                    }
                } else {
                    *color
                };
                self.pixels[idx] = Some(new);
            }
        }
    }

    pub fn draw_checkerboard(
        &mut self,
        row: usize,
        col: usize,
        height: usize,
        width: usize,
        dark: &Color,
        light: &Color,
    ) {
        for i in 0..height {
            for j in 0..width {
                let r = row + i;
                let c = col + j;
                if r >= self.height || c >= self.width {
                    continue;
                }
                let color = if (i + j) % 2 == 0 { light } else { dark };
                let idx = self.idx(r, c);
                self.pixels[idx] = Some(*color);
            }
        }
    }

    pub fn draw_text(&mut self, row: usize, col: usize, text: &str) {
        for (i, ch) in text.chars().enumerate() {
            let c = col + i;
            if row < self.height / 2 && c < self.width {
                let idx = row * self.width + c;
                self.chars[idx] = Some(ch);
            }
        }
    }

    pub fn print(&self, out: &mut dyn Write) -> std::io::Result<()> {
        let mut s = String::new();
        for i_line in 0..self.height / 2 {
            for j in 0..self.width {
                if let Some(ch) = self.chars[i_line * self.width + j] {
                    s.push(ch);
                    continue;
                }
                let top = self.pixels[self.idx(2 * i_line, j)];
                let bottom = self.pixels[self.idx(2 * i_line + 1, j)];
                match (top, bottom) {
                    (Some(t), Some(b)) => {
                        if t == b {
                            s.push_str(&self.brush.paint(" ", &Style::new().foreground(&t).on(&b)));
                        } else {
                            s.push_str(&self.brush.paint("\u{2580}", &Style::new().foreground(&t).on(&b)));
                        }
                    }
                    (Some(t), None) => {
                        s.push_str(&self.brush.paint("\u{2580}", &Style::new().foreground(&t)));
                    }
                    (None, Some(b)) => {
                        s.push_str(&self.brush.paint("\u{2584}", &Style::new().foreground(&b)));
                    }
                    (None, None) => s.push(' '),
                }
            }
            s.push('\n');
        }
        out.write_all(s.as_bytes())
    }
}
