//! Minimal text wrapping (greedy, space separated), compatible with clap's algorithm.

pub fn display_width(s: &str) -> usize {
    s.chars().count()
}

fn find_words(line: &str) -> Vec<&str> {
    let mut words = Vec::new();
    let mut start = 0;
    let mut in_ws = false;
    for (idx, ch) in line.char_indices() {
        if in_ws && ch != ' ' {
            words.push(&line[start..idx]);
            start = idx;
        }
        in_ws = ch == ' ';
    }
    if start < line.len() {
        words.push(&line[start..]);
    }
    words
}

pub fn wrap(content: &str, hard_width: usize) -> String {
    let mut total: Vec<&str> = Vec::new();
    let mut rest = content;
    while !rest.is_empty() {
        let (line, remainder) = match rest.find('\n') {
            Some(i) => (&rest[..=i], &rest[i + 1..]),
            None => (rest, ""),
        };
        rest = remainder;
        let mut words = find_words(line);
        let mut line_width = 0usize;
        let mut i = 0;
        while i < words.len() {
            let word = words[i];
            let trimmed = word.trim_end();
            let word_width = display_width(trimmed);
            let trimmed_delta = display_width(word) - word_width;
            if i != 0 && hard_width < line_width + word_width {
                let last = i - 1;
                words[last] = words[last].trim_end();
                words.insert(i, "\n");
                i += 1;
                line_width = 0;
            }
            line_width += word_width + trimmed_delta;
            i += 1;
        }
        total.extend(words);
    }
    total.concat()
}

/// Indent every line after a newline with `trailing` (first line with `initial`).
pub fn indent(s: &str, initial: &str, trailing: &str) -> String {
    let mut out = String::new();
    out.push_str(initial);
    let mut first = true;
    for part in s.split_inclusive('\n') {
        if !first {
            out.push_str(trailing);
        }
        first = false;
        out.push_str(part);
    }
    out
}
EOF
