#[derive(Debug, Clone)]
pub struct ArgDef {
    pub id: &'static str,
    pub short: Option<char>,
    pub long: Option<&'static str>,
    pub value_name: Option<&'static str>,
    pub positional: bool,
    pub required: bool,
    pub multiple: bool,
    pub default: Option<&'static str>,
    pub possible: &'static [&'static str],
    pub hide_possible: bool,
    pub ignore_case: bool,
    pub help: &'static str,
}

impl ArgDef {
    const fn pos(id: &'static str, required: bool, multiple: bool, help: &'static str) -> ArgDef {
        ArgDef {
            id,
            short: None,
            long: None,
            value_name: None,
            positional: true,
            required,
            multiple,
            default: None,
            possible: &[],
            hide_possible: false,
            ignore_case: false,
            help,
        }
    }
    const fn flag(id: &'static str, short: char, long: &'static str, help: &'static str) -> ArgDef {
        ArgDef {
            id,
            short: Some(short),
            long: Some(long),
            value_name: None,
            positional: false,
            required: false,
            multiple: false,
            default: None,
            possible: &[],
            hide_possible: false,
            ignore_case: false,
            help,
        }
    }
    const fn opt(id: &'static str, short: Option<char>, long: &'static str, value_name: &'static str, help: &'static str) -> ArgDef {
        ArgDef {
            id,
            short,
            long: Some(long),
            value_name: Some(value_name),
            positional: false,
            required: false,
            multiple: false,
            default: None,
            possible: &[],
            hide_possible: false,
            ignore_case: false,
            help,
        }
    }
    const fn default(mut self, d: &'static str) -> ArgDef {
        self.default = Some(d);
        self
    }
    const fn possible(mut self, p: &'static [&'static str]) -> ArgDef {
        self.possible = p;
        self
    }
    const fn hide_possible(mut self) -> ArgDef {
        self.hide_possible = true;
        self
    }
    const fn ignore_case(mut self) -> ArgDef {
        self.ignore_case = true;
        self
    }
    pub fn takes_value(&self) -> bool {
        self.positional || self.value_name.is_some()
    }
    /// e.g. "[color]..." or "<count>" for positionals, "--number <count>" for options
    pub fn display(&self) -> String {
        if self.positional {
            let mut s = if self.required {
                format!("<{}>", self.id)
            } else {
                format!("[{}]", self.id)
            };
            if self.multiple {
                s.push_str("...");
            }
            s
        } else {
            let mut s = format!("--{}", self.long.unwrap_or(""));
            if let Some(v) = self.value_name {
                s.push_str(&format!(" <{}>", v));
            }
            s
        }
    }
    /// e.g. "-s, --strategy <strategy>" (the help table entry)
    pub fn help_entry(&self) -> String {
        if self.positional {
            self.display()
        } else {
            let mut s = String::new();
            match self.short {
                Some(c) => {
                    s.push('-');
                    s.push(c);
                    s.push_str(", ");
                }
                None => s.push_str("    "),
            }
            s.push_str(&self.display());
            s
        }
    }
}

