/// Result of parsing the command line.
#[derive(Debug, Default)]
pub struct Matches {
    pub values: HashMap<String, Vec<String>>,
    pub flags: HashMap<String, bool>,
}

impl Matches {
    pub fn get(&self, id: &str) -> Option<&str> {
        self.values.get(id).and_then(|v| v.first()).map(|s| s.as_str())
    }
    pub fn get_many(&self, id: &str) -> Vec<String> {
        self.values.get(id).cloned().unwrap_or_default()
    }
    pub fn is_present(&self, id: &str) -> bool {
        self.flags.get(id).copied().unwrap_or(false) || self.values.contains_key(id)
    }
}

pub enum Exit {
    /// Print to stdout, exit 0
    Stdout(String),
    /// Print to stderr, exit 2
    Stderr(String),
}

pub struct ParsedCli {
    pub color_picker: Option<String>,
    pub force_color: bool,
    pub color_mode: Option<String>,
    pub command: String,
    pub matches: Matches,
}

// ----------------------------------------------------------------------------
// similarity
// ----------------------------------------------------------------------------

pub fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    let search_range = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut a_flags = vec![false; a.len()];
    let mut b_flags = vec![false; b.len()];
    let mut matches = 0usize;
    for (i, ca) in a.iter().enumerate() {
        let lo = i.saturating_sub(search_range);
        let hi = (i + search_range + 1).min(b.len());
        for j in lo..hi {
            if !b_flags[j] && b[j] == *ca {
                a_flags[i] = true;
                b_flags[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut t = 0usize;
    let mut k = 0usize;
    for i in 0..a.len() {
        if a_flags[i] {
            while !b_flags[k] {
                k += 1;
            }
            if a[i] != b[k] {
                t += 1;
            }
            k += 1;
        }
    }
    let t = t / 2;
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - t as f64) / m) / 3.0
}

pub fn did_you_mean<'a, I: IntoIterator<Item = &'a str>>(v: &str, candidates: I) -> Vec<String> {
    let mut c: Vec<(f64, String)> = candidates
        .into_iter()
        .map(|pv| (jaro(v, pv), pv.to_string()))
        .filter(|(conf, _)| *conf > 0.7)
        .collect();
    c.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    c.into_iter().map(|(_, pv)| pv).collect()
}

// ----------------------------------------------------------------------------
// help rendering
// ----------------------------------------------------------------------------

const TAB: &str = "  ";
const TAB_WIDTH: usize = 2;
const NEXT_LINE_INDENT: &str = "        ";

pub struct HelpCtx {
    pub bin: String,
    pub term_w: usize,
}

fn spec_vals(arg: &ArgDef, use_long: bool) -> String {
    let mut sv: Vec<String> = Vec::new();
    if arg.takes_value() {
        if let Some(d) = arg.default {
            sv.push(format!("[default: {}]", d));
        }
    }
    if !arg.hide_possible && !arg.possible.is_empty() {
        sv.push(format!("[possible values: {}]", arg.possible.join(", ")));
    }
    let connector = if use_long { "\n" } else { " " };
    sv.join(connector)
}

fn help_flag_text(long_exists: bool, use_long: bool) -> &'static str {
    if !long_exists {
        "Print help"
    } else if use_long {
        "Print help (see a summary with '-h')"
    } else {
        "Print help (see more with '--help')"
    }
}

struct HelpArg {
    entry: String,
    display_w: usize,
    positional: bool,
    help: String,
    spec: String,
}

fn arg_next_line_help(h: &HelpArg, longest: usize, term_w: usize, use_long: bool) -> bool {
    if use_long {
        return true;
    }
    let h_w = display_width(&h.help) + display_width(&h.spec);
    let taken = if h.positional { longest + TAB_WIDTH * 2 } else { longest + TAB_WIDTH * 2 + 4 };
    term_w >= taken && (taken as f32 / term_w as f32) > 0.40 && h_w > (term_w - taken)
}

fn write_help_text(out: &mut String, help: &str, spec: &str, next_line: bool, spaces: usize, term_w: usize, use_long_sep: bool) {
    if next_line {
        out.push('\n');
        out.push_str(TAB);
        out.push_str(NEXT_LINE_INDENT);
    }
    let mut text = help.to_string();
    if !spec.is_empty() {
        if !text.is_empty() {
            text.push_str(if use_long_sep { "\n\n" } else { " " });
        }
        text.push_str(spec);
    }
    let avail = term_w.saturating_sub(spaces);
    let wrapped = wrap(&text, avail);
    let trailing = " ".repeat(spaces);
    out.push_str(&indent(&wrapped, "", &trailing));
}

fn write_args(out: &mut String, args: &[HelpArg], term_w: usize, use_long: bool) {
    let mut longest = 2usize;
    for a in args {
        longest = longest.max(a.display_w);
    }
    let next_line_help = args.iter().any(|a| arg_next_line_help(a, longest, term_w, use_long));
    for (i, a) in args.iter().enumerate() {
        if i != 0 {
            out.push('\n');
            if next_line_help && use_long {
                out.push('\n');
            }
        }
        out.push_str(TAB);
        out.push_str(&a.entry);
        let spaces = if next_line_help {
            TAB_WIDTH + NEXT_LINE_INDENT.len()
        } else if a.positional {
            longest + TAB_WIDTH * 2
        } else {
            longest + TAB_WIDTH * 2 + 4
        };
        if !next_line_help {
            let pad = if a.positional {
                longest + TAB_WIDTH - a.display_w
            } else {
                longest + TAB_WIDTH - a.display_w
            };
            out.push_str(&" ".repeat(pad));
        }
        write_help_text(out, &a.help, &a.spec, next_line_help, spaces, term_w, use_long);
    }
}

fn option_entry_width(arg: &ArgDef) -> usize {
    // clap measures the "--long <val>" part (without the short flag section)
    display_width(&arg.display())
}

pub fn render_subcommand_help(ctx: &HelpCtx, cmd: &CmdDef, use_long: bool) -> String {
    let long_exists = cmd.long_about.is_some();
    let use_long = use_long && long_exists;
    let mut out = String::new();
    let about = if use_long { cmd.long_about.unwrap() } else { cmd.about };
    out.push_str(&wrap(about, ctx.term_w));
    out.push('\n');
    out.push('\n');
    out.push_str(&format!("Usage: {}\n", usage_plain(ctx, cmd)));
    out.push('\n');
    let positionals: Vec<HelpArg> = cmd
        .args
        .iter()
        .filter(|a| a.positional)
        .map(|a| HelpArg {
            entry: a.help_entry(),
            display_w: display_width(&a.display()),
            positional: true,
            help: a.help.to_string(),
            spec: spec_vals(a, use_long),
        })
        .collect();
    let mut options: Vec<HelpArg> = cmd
        .args
        .iter()
        .filter(|a| !a.positional)
        .map(|a| HelpArg {
            entry: a.help_entry(),
            display_w: option_entry_width(a),
            positional: false,
            help: a.help.to_string(),
            spec: spec_vals(a, use_long),
        })
        .collect();
    options.push(HelpArg {
        entry: "-h, --help".to_string(),
        display_w: display_width("--help"),
        positional: false,
        help: help_flag_text(long_exists, use_long).to_string(),
        spec: String::new(),
    });
    let mut first = true;
    if !positionals.is_empty() {
        out.push_str("Arguments:\n");
        write_args(&mut out, &positionals, ctx.term_w, use_long);
        first = false;
    }
    if !first {
        out.push_str("\n\n");
    }
    out.push_str("Options:\n");
    write_args(&mut out, &options, ctx.term_w, use_long);
    out.push('\n');
    out
}

pub fn render_help_subcommand_help(ctx: &HelpCtx) -> String {
    let mut out = String::new();
    out.push_str("Print this message or the help of the given subcommand(s)\n\n");
    out.push_str(&format!("Usage: {} help [COMMAND]...\n\n", ctx.bin));
    out.push_str("Arguments:\n");
    let args = vec![HelpArg {
        entry: "[COMMAND]...".to_string(),
        display_w: display_width("[COMMAND]..."),
        positional: true,
        help: "Print help for the subcommand(s)".to_string(),
        spec: String::new(),
    }];
    write_args(&mut out, &args, ctx.term_w, false);
    out.push('\n');
    out
}

pub fn render_main_help(ctx: &HelpCtx) -> String {
    let mut out = String::new();
    out.push_str(&wrap(MAIN_ABOUT, ctx.term_w));
    out.push_str("\n\n");
    out.push_str(&format!("Usage: {} [OPTIONS] <COMMAND>\n\n", ctx.bin));
    // Commands
    out.push_str("Commands:\n");
    let mut cmds: Vec<(String, String)> = commands().iter().map(|c| (c.name.to_string(), c.about.to_string())).collect();
    cmds.push(("help".to_string(), "Print this message or the help of the given subcommand(s)".to_string()));
    cmds.sort();
    let mut longest = 2usize;
    for (n, _) in &cmds {
        longest = longest.max(display_width(n));
    }
    let next_line_help = cmds.iter().any(|(_, about)| {
        let taken = longest + TAB_WIDTH * 2;
        let h_w = display_width(about);
        ctx.term_w >= taken && (taken as f32 / ctx.term_w as f32) > 0.40 && h_w > (ctx.term_w - taken)
    });
    for (i, (n, about)) in cmds.iter().enumerate() {
        if i != 0 {
            out.push('\n');
        }
        out.push_str(TAB);
        out.push_str(n);
        if !next_line_help {
            out.push_str(&" ".repeat(longest + TAB_WIDTH - display_width(n)));
        }
        let spaces = if next_line_help { TAB_WIDTH + NEXT_LINE_INDENT.len() } else { longest + TAB_WIDTH * 2 };
        write_help_text(&mut out, about, "", next_line_help, spaces, ctx.term_w, false);
    }
    out.push_str("\n\n");
    out.push_str("Options:\n");
    let options: Vec<HelpArg> = main_options()
        .iter()
        .map(|a| HelpArg {
            entry: a.help_entry(),
            display_w: option_entry_width(a),
            positional: false,
            help: a.help.to_string(),
            spec: spec_vals(a, false),
        })
        .collect();
    write_args(&mut out, &options, ctx.term_w, false);
    out.push('\n');
    out
}

/// "executable paint [OPTIONS] <color> [text]..."
pub fn usage_plain(ctx: &HelpCtx, cmd: &CmdDef) -> String {
    let mut s = format!("{} {}", ctx.bin, cmd.name);
    if cmd.args.iter().any(|a| !a.positional) {
        s.push_str(" [OPTIONS]");
    }
    for a in cmd.args.iter().filter(|a| a.positional) {
        s.push(' ');
        s.push_str(&a.display());
    }
    s
}

/// "executable paint --bold --on <bg-color> <color> [text]..."
pub fn usage_smart(ctx: &HelpCtx, cmd: &CmdDef, used_options: &[String], used_positionals: &[String]) -> String {
    let mut s = format!("{} {}", ctx.bin, cmd.name);
    for id in used_options {
        if let Some(a) = cmd.args.iter().find(|a| a.id == *id) {
            s.push(' ');
            s.push_str(&a.display());
        }
    }
    for a in cmd.args.iter().filter(|a| a.positional) {
        s.push(' ');
        let used = used_positionals.iter().any(|u| u == a.id);
        let mut d = if a.required || used { format!("<{}>", a.id) } else { format!("[{}]", a.id) };
        if a.multiple {
            d.push_str("...");
        }
        s.push_str(&d);
    }
    s
}

pub fn usage_main_plain(ctx: &HelpCtx) -> String {
    format!("{} [OPTIONS] <COMMAND>", ctx.bin)
}

pub fn usage_main_smart(ctx: &HelpCtx, used: &[String]) -> String {
    let mut s = ctx.bin.clone();
    let opts = main_options();
    for id in used {
        if let Some(a) = opts.iter().find(|a| a.id == *id) {
            s.push(' ');
            s.push_str(&a.display());
        }
    }
    s.push_str(" <COMMAND>");
    s
}

fn err_with_usage(msg: &str, tip: Option<String>, usage: Option<String>) -> Exit {
    let mut s = format!("error: {}\n", msg);
    if let Some(t) = tip {
        s.push('\n');
        s.push_str(&t);
        s.push('\n');
    }
    if let Some(u) = usage {
        s.push('\n');
        s.push_str(&format!("Usage: {}\n", u));
    }
    s.push_str("\nFor more information, try '--help'.\n");
    Exit::Stderr(s)
}

fn all_subcommand_names() -> Vec<String> {
    let mut v = Vec::new();
    for c in commands() {
        v.push(c.name.to_string());
        for a in c.aliases {
            v.push(a.to_string());
        }
    }
    v.push("help".to_string());
    v
}

fn subcommand_tip(name: &str) -> Option<String> {
    let names = all_subcommand_names();
    let sugg = did_you_mean(name, names.iter().map(|s| s.as_str()));
    if sugg.is_empty() {
        None
    } else if sugg.len() == 1 {
        Some(format!("  tip: a similar subcommand exists: '{}'", sugg[0]))
    } else {
        let list: Vec<String> = sugg.iter().map(|s| format!("'{}'", s)).collect();
        Some(format!("  tip: some similar subcommands exist: {}", list.join(", ")))
    }
}

fn find_command(name: &str) -> Option<CmdDef> {
    commands().into_iter().find(|c| c.name == name || c.aliases.contains(&name))
}

fn invalid_value_error(value: &str, arg: &ArgDef) -> Exit {
    let mut s = format!("error: invalid value '{}' for '{}'\n", value, arg.display());
    s.push_str(&format!("  [possible values: {}]\n", arg.possible.join(", ")));
    let sugg = did_you_mean(value, arg.possible.iter().copied());
    if let Some(best) = sugg.last() {
        s.push_str(&format!("\n  tip: a similar value exists: '{}'\n", best));
    }
    s.push_str("\nFor more information, try '--help'.\n");
    Exit::Stderr(s)
}

fn value_required_error(arg: &ArgDef) -> Exit {
    let mut s = format!("error: a value is required for '{}' but none was supplied\n", arg.display());
    if !arg.possible.is_empty() {
        s.push_str(&format!("  [possible values: {}]\n", arg.possible.join(", ")));
    }
    s.push_str("\nFor more information, try '--help'.\n");
    Exit::Stderr(s)
}

/// Validate a value against possible values; returns canonical value.
fn validate_value(arg: &ArgDef, value: &str) -> Result<String, Exit> {
    if arg.possible.is_empty() {
        return Ok(value.to_string());
    }
    if value.is_empty() {
        return Err(value_required_error(arg));
    }
    for p in arg.possible {
        if *p == value || (arg.ignore_case && p.eq_ignore_ascii_case(value)) {
            return Ok(p.to_string());
        }
    }
    Err(invalid_value_error(value, arg))
}

/// Parse the full command line. `args` excludes the binary name.
pub fn parse(ctx: &HelpCtx, args: &[String]) -> Result<ParsedCli, Exit> {
    let opts = main_options();
    let mut color_picker: Option<String> = None;
    let mut force_color = false;
    let mut color_mode: Option<String> = None;
    let mut used: Vec<String> = Vec::new();
    let mut i = 0;
    let mut after_dd = false;
    while i < args.len() {
        let a = &args[i];
        if !after_dd && a == "--" {
            after_dd = true;
            i += 1;
            continue;
        }
        if !after_dd && a.starts_with("--") {
            let (name, inline) = match a[2..].find('=') {
                Some(p) => (&a[2..2 + p], Some(a[3 + p..].to_string())),
                None => (&a[2..], None),
            };
            match name {
                "help" => {
                    if let Some(v) = inline {
                        return Err(err_with_usage(
                            &format!("unexpected value '{}' for '--help' found; no more were expected", v),
                            None,
                            Some(format!("{} --help <COMMAND>", ctx.bin)),
                        ));
                    }
                    return Err(Exit::Stdout(render_main_help(ctx)));
                }
                "version" => {
                    if let Some(v) = inline {
                        return Err(err_with_usage(
                            &format!("unexpected value '{}' for '--version' found; no more were expected", v),
                            None,
                            Some(format!("{} --version <COMMAND>", ctx.bin)),
                        ));
                    }
                    return Err(Exit::Stdout(format!("pastel {}\n", VERSION)));
                }
                "force-color" => {
                    if let Some(v) = inline {
                        return Err(err_with_usage(
                            &format!("unexpected value '{}' for '--force-color' found; no more were expected", v),
                            None,
                            Some(usage_main_smart(ctx, &used_plus(&used, "force-color"))),
                        ));
                    }
                    if force_color {
                        return Err(err_with_usage(
                            "the argument '--force-color' cannot be used multiple times",
                            None,
                            Some(usage_main_plain(ctx)),
                        ));
                    }
                    force_color = true;
                    used.push("force-color".into());
                    i += 1;
                }
                "color-mode" | "color-picker" => {
                    let def = opts.iter().find(|o| o.long == Some(name)).unwrap();
                    let target_set = if name == "color-mode" { color_mode.is_some() } else { color_picker.is_some() };
                    if target_set {
                        return Err(err_with_usage(
                            &format!("the argument '{}' cannot be used multiple times", def.display()),
                            None,
                            Some(usage_main_plain(ctx)),
                        ));
                    }
                    let value = match inline {
                        Some(v) => v,
                        None => {
                            i += 1;
                            match args.get(i) {
                                Some(v) => v.clone(),
                                None => return Err(value_required_error(def)),
                            }
                        }
                    };
                    let v = validate_value(def, &value)?;
                    if name == "color-mode" {
                        color_mode = Some(v);
                    } else {
                        color_picker = Some(v);
                    }
                    used.push(name.to_string());
                    i += 1;
                }
                _ => {
                    let longs: Vec<&str> = opts.iter().filter_map(|o| o.long).collect();
                    let sugg = did_you_mean(name, longs.iter().copied());
                    let display = format!("--{}", name);
                    if let Some(best) = sugg.last() {
                        let def = opts.iter().find(|o| o.long == Some(best.as_str())).unwrap();
                        let mut u = used.clone();
                        u.push(def.id.to_string());
                        return Err(err_with_usage(
                            &format!("unexpected argument '{}' found", display),
                            Some(format!("  tip: a similar argument exists: '--{}'", best)),
                            Some(usage_main_smart(ctx, &u)),
                        ));
                    }
                    let usage = if used.is_empty() { usage_main_plain(ctx) } else { usage_main_smart(ctx, &used) };
                    return Err(err_with_usage(&format!("unexpected argument '{}' found", display), None, Some(usage)));
                }
            }
            continue;
        }
        if !after_dd && a.starts_with('-') && a.len() > 1 {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut k = 0;
            while k < chars.len() {
                let c = chars[k];
                match c {
                    'h' => return Err(Exit::Stdout(render_main_help(ctx))),
                    'V' => return Err(Exit::Stdout(format!("pastel {}\n", VERSION))),
                    'f' => {
                        if force_color {
                            return Err(err_with_usage(
                                "the argument '--force-color' cannot be used multiple times",
                                None,
                                Some(usage_main_plain(ctx)),
                            ));
                        }
                        force_color = true;
                        used.push("force-color".into());
                        k += 1;
                    }
                    'm' => {
                        let def = opts.iter().find(|o| o.id == "color-mode").unwrap();
                        if color_mode.is_some() {
                            return Err(err_with_usage(
                                &format!("the argument '{}' cannot be used multiple times", def.display()),
                                None,
                                Some(usage_main_plain(ctx)),
                            ));
                        }
                        let rest: String = chars[k + 1..].iter().collect();
                        let value = if !rest.is_empty() {
                            rest.strip_prefix('=').unwrap_or(&rest).to_string()
                        } else {
                            i += 1;
                            match args.get(i) {
                                Some(v) => v.clone(),
                                None => return Err(value_required_error(def)),
                            }
                        };
                        let v = validate_value(def, &value)?;
                        color_mode = Some(v);
                        used.push("color-mode".into());
                        k = chars.len();
                    }
                    _ => {
                        return Err(err_with_usage(
                            &format!("unexpected argument '-{}' found", c),
                            None,
                            Some(usage_main_plain(ctx)),
                        ));
                    }
                }
            }
            i += 1;
            continue;
        }
        // subcommand
        if a == "help" {
            return parse_help_subcommand(ctx, &args[i + 1..]);
        }
        match find_command(a) {
            Some(cmd) => {
                if after_dd {
                    return Err(err_with_usage(
                        &format!("unexpected argument '{}' found", a),
                        Some(format!("  tip: subcommand '{}' exists; to use it, remove the '--' before it", a)),
                        Some(usage_main_plain(ctx)),
                    ));
                }
                let matches = parse_subcommand(ctx, &cmd, &args[i + 1..])?;
                return Ok(ParsedCli {
                    color_picker,
                    force_color,
                    color_mode,
                    command: cmd.name.to_string(),
                    matches,
                });
            }
            None => {
                if after_dd && a == "help" {
                    // unreachable (handled above)
                }
                return Err(err_with_usage(
                    &format!("unrecognized subcommand '{}'", a),
                    subcommand_tip(a),
                    Some(usage_main_plain(ctx)),
                ));
            }
        }
    }
    if used.is_empty() {
        return Err(Exit::Stderr(render_main_help(ctx)));
    }
    let names = all_subcommand_names();
    Err(err_with_usage(
        &format!("'{}' requires a subcommand but one was not provided\n  [subcommands: {}]", ctx.bin, names.join(", ")),
        None,
        Some(usage_main_plain(ctx)),
    ))
}

fn used_plus(used: &[String], id: &str) -> Vec<String> {
    let mut u = used.to_vec();
    if !u.iter().any(|x| x == id) {
        u.push(id.to_string());
    }
    u
}

fn parse_help_subcommand(ctx: &HelpCtx, rest: &[String]) -> Result<ParsedCli, Exit> {
    if rest.is_empty() {
        return Err(Exit::Stdout(render_main_help(ctx)));
    }
    let name = &rest[0];
    if name == "help" {
        if rest.len() > 1 {
            return Err(err_with_usage(
                &format!("unrecognized subcommand '{}'", rest[1]),
                None,
                Some(format!("{} help [COMMAND]...", ctx.bin)),
            ));
        }
        return Err(Exit::Stdout(render_help_subcommand_help(ctx)));
    }
    match find_command(name) {
        Some(cmd) => {
            if rest.len() > 1 {
                return Err(err_with_usage(
                    &format!("unrecognized subcommand '{}'", rest[1]),
                    None,
                    Some(usage_plain(ctx, &cmd)),
                ));
            }
            Err(Exit::Stdout(render_subcommand_help(ctx, &cmd, true)))
        }
        None => Err(err_with_usage(
            &format!("unrecognized subcommand '{}'", name),
            subcommand_tip(name),
            Some(usage_main_plain(ctx)),
        )),
    }
}

fn parse_subcommand(ctx: &HelpCtx, cmd: &CmdDef, args: &[String]) -> Result<Matches, Exit> {
    let mut m = Matches::default();
    let positionals: Vec<&ArgDef> = cmd.args.iter().filter(|a| a.positional).collect();
    let has_positionals = !positionals.is_empty();
    let mut pos_index = 0usize;
    let mut used_options: Vec<String> = Vec::new();
    let mut used_positionals: Vec<String> = Vec::new();
    let mut after_dd = false;
    let mut i = 0;

    let plain = |ctx: &HelpCtx| usage_plain(ctx, cmd);

    while i < args.len() {
        let a = &args[i];
        if !after_dd && a == "--" {
            after_dd = true;
            i += 1;
            continue;
        }
        if !after_dd && a.starts_with("--") && a.len() > 2 {
            let (name, inline) = match a[2..].find('=') {
                Some(p) => (&a[2..2 + p], Some(a[3 + p..].to_string())),
                None => (&a[2..], None),
            };
            if name == "help" {
                if let Some(v) = inline {
                    let smart = usage_smart(ctx, cmd, &used_plus(&used_options, "help"), &used_positionals);
                    return Err(err_with_usage(
                        &format!("unexpected value '{}' for '--help' found; no more were expected", v),
                        None,
                        Some(smart.replace(&format!("{} {}", ctx.bin, cmd.name), &format!("{} {} --help", ctx.bin, cmd.name))),
                    ));
                }
                return Err(Exit::Stdout(render_subcommand_help(ctx, cmd, true)));
            }
            match cmd.args.iter().find(|o| !o.positional && o.long == Some(name)) {
                Some(def) => {
                    if def.takes_value() {
                        if m.values.contains_key(def.id) {
                            return Err(err_with_usage(
                                &format!("the argument '{}' cannot be used multiple times", def.display()),
                                None,
                                Some(plain(ctx)),
                            ));
                        }
                        let value = match inline {
                            Some(v) => v,
                            None => {
                                i += 1;
                                match args.get(i) {
                                    Some(v) if !(v.starts_with('-') && v.len() > 1 && v != "-") => v.clone(),
                                    Some(_) | None => return Err(value_required_error(def)),
                                }
                            }
                        };
                        let v = validate_value(def, &value)?;
                        m.values.insert(def.id.to_string(), vec![v]);
                        used_options.push(def.id.to_string());
                    } else {
                        if let Some(v) = inline {
                            let u = used_plus(&used_options, def.id);
                            return Err(err_with_usage(
                                &format!("unexpected value '{}' for '{}' found; no more were expected", v, def.display()),
                                None,
                                Some(usage_smart(ctx, cmd, &u, &used_positionals)),
