                            return Err(err_with_usage(
                                &format!("the argument '{}' cannot be used multiple times", def.display()),
                                None,
                                Some(plain(ctx)),
                            ));
                        }
                        m.flags.insert(def.id.to_string(), true);
                        used_options.push(def.id.to_string());
                    }
                    i += 1;
                }
                None => {
                    let mut longs: Vec<&str> = cmd.args.iter().filter_map(|o| o.long).collect();
                    longs.push("help");
                    let sugg = did_you_mean(name, longs.iter().copied());
                    let display = format!("--{}", name);
                    if let Some(best) = sugg.last() {
                        let u = match cmd.args.iter().find(|o| o.long == Some(best.as_str())) {
                            Some(def) => used_plus(&used_options, def.id),
                            None => used_options.clone(),
                        };
                        let usage = if best == "help" {
                            let s = usage_smart(ctx, cmd, &u, &used_positionals);
                            s.replace(&format!("{} {}", ctx.bin, cmd.name), &format!("{} {} --help", ctx.bin, cmd.name))
                        } else {
                            usage_smart(ctx, cmd, &u, &used_positionals)
                        };
                        return Err(err_with_usage(
                            &format!("unexpected argument '{}' found", display),
                            Some(format!("  tip: a similar argument exists: '--{}'", best)),
                            Some(usage),
                        ));
                    }
                    let tip = if has_positionals {
                        Some(format!("  tip: to pass '{}' as a value, use '-- {}'", display, display))
                    } else {
                        None
                    };
                    let usage = if used_options.is_empty() && used_positionals.is_empty() {
                        plain(ctx)
                    } else {
                        usage_smart(ctx, cmd, &used_options, &used_positionals)
                    };
                    return Err(err_with_usage(&format!("unexpected argument '{}' found", display), tip, Some(usage)));
                }
            }
            continue;
