                let c = chars[k];
                if c == 'h' {
                    return Err(Exit::Stdout(render_subcommand_help(ctx, cmd, false)));
                }
                match cmd.args.iter().find(|o| !o.positional && o.short == Some(c)) {
                    Some(def) => {
                        if def.takes_value() {
                            if m.values.contains_key(def.id) {
                                return Err(err_with_usage(
                                    &format!("the argument '{}' cannot be used multiple times", def.display()),
                                    None,
                                    Some(plain(ctx)),
                                ));
                            }
                            let rest: String = chars[k + 1..].iter().collect();
                            let value = if !rest.is_empty() {
                                rest.strip_prefix('=').unwrap_or(&rest).to_string()
                            } else {
                                i += 1;
                                match args.get(i) {
                                    Some(v) if !(v.starts_with('-') && v.len() > 1 && v != "-") => v.clone(),
                                    Some(_) | None => return Err(value_required_error(def)),
                                }
                            };
                            let v = validate_value(def, &value)?;
                            m.values.insert(def.id.to_string(), vec![v]);
                            used_options.push(def.id.to_string());
                            k = chars.len();
                        } else {
                            if m.flags.contains_key(def.id) {
                                return Err(err_with_usage(
                                    &format!("the argument '{}' cannot be used multiple times", def.display()),
                                    None,
                                    Some(plain(ctx)),
                                ));
                            }
                            m.flags.insert(def.id.to_string(), true);
                            used_options.push(def.id.to_string());
                            k += 1;
                        }
                    }
                    None => {
                        let display = format!("-{}", c);
                        let tip = if has_positionals {
                            Some(format!("  tip: to pass '{}' as a value, use '-- {}'", display, display))
                        } else {
                            None
                        };
                        return Err(err_with_usage(&format!("unexpected argument '{}' found", display), tip, Some(plain(ctx))));
                    }
                }
            }
            i += 1;
            continue;
        }
        // positional value
        if pos_index >= positionals.len() {
            return Err(err_with_usage(&format!("unexpected argument '{}' found", a), None, Some(plain(ctx))));
        }
        let def = positionals[pos_index];
        let v = validate_value(def, a)?;
        m.values.entry(def.id.to_string()).or_default().push(v);
        if !used_positionals.iter().any(|u| u == def.id) {
            used_positionals.push(def.id.to_string());
        }
        if !def.multiple {
            pos_index += 1;
        }
        i += 1;
    }
    // required check
    let missing: Vec<String> = positionals
        .iter()
        .filter(|p| p.required && !m.values.contains_key(p.id))
        .map(|p| p.display())
        .collect();
    if !missing.is_empty() {
        let mut msg = String::from("the following required arguments were not provided:");
        for mi in &missing {
            msg.push_str(&format!("\n  {}", mi));
        }
        let usage = if used_options.is_empty() && used_positionals.is_empty() {
            plain(ctx)
        } else {
            usage_smart(ctx, cmd, &used_options, &used_positionals)
        };
        return Err(err_with_usage(&msg, None, Some(usage)));
    }
    // defaults
    for a in &cmd.args {
        if let Some(d) = a.default {
            if a.takes_value() && !m.values.contains_key(a.id) {
                m.values.insert(a.id.to_string(), vec![d.to_string()]);
            }
        }
    }
    Ok(m)
}
