                    return Err(Exit::Stdout(render_subcommand_help(ctx, cmd, false)));
                }
                let def = def.unwrap();
                if def.takes_value() {
                    if m.values.contains_key(def.id) {
                        return Err(err_with_usage(
                            &format!("the argument '{}' cannot be used multiple times", def.display()),
                            None,
