use std::io::IsTerminal;

#[repr(C)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

const TIOCGWINSZ: u64 = 0x5413;

/// Width of the terminal attached to stdout (if any).
pub fn stdout_width() -> Option<usize> {
    if !std::io::stdout().is_terminal() {
        return None;
    }
    let mut ws = WinSize {
        ws_row: 0,
        ws_col: 0,
        ws_xpixel: 0,
        ws_ypixel: 0,
    };
    let r = unsafe { ioctl(1, TIOCGWINSZ, &mut ws as *mut WinSize) };
    if r == 0 && ws.ws_col > 0 {
        Some(ws.ws_col as usize)
    } else {
        None
    }
}

/// Width used for help output (clap compatible): terminal width, else $COLUMNS, else 100; capped at 100.
pub fn help_width() -> usize {
    let w = stdout_width().or_else(|| {
        std::env::var("COLUMNS").ok().and_then(|c| c.trim().parse::<usize>().ok())
    });
    let w = w.unwrap_or(100);
    w.min(100)
}
