//! Error type.

#[derive(Debug)]
pub enum PastelError {
    ColorParseError(String),
    CouldNotReadFromStdin,
    ColorArgRequired,
    CouldNotParseNumber(String),
    StdoutClosed,
    ColorPickerExecutionError(String),
    NoColorPickerFound,
    UnknownColorMode(String),
    GradientColorCount,
    GradientNumberOfColors,
    DistinctColorCount,
    DistinctColorFixedColorsCount,
    IoError(std::io::Error),
}

impl PastelError {
    pub fn message(&self) -> String {
        match self {
            PastelError::ColorParseError(s) => format!("Could not parse color '{}'", s),
            PastelError::CouldNotReadFromStdin => "Could not read color from standard input".into(),
            PastelError::ColorArgRequired => "A color argument needs to be provided on the command line or via a pipe. Call this command again with '-h' or '--help' to get more information.".into(),
            PastelError::CouldNotParseNumber(s) => format!("Could not parse number '{}'", s),
            PastelError::StdoutClosed => "Output pipe has been closed".into(),
            PastelError::ColorPickerExecutionError(name) => format!("Error while running color picker '{}'", name),
            PastelError::NoColorPickerFound => "Could not find any external color picker tool. See 'pastel pick --help' for more information.".into(),
            PastelError::UnknownColorMode(s) => format!("Unknown PASTEL_COLOR_MODE value ({})", s),
            PastelError::GradientColorCount => "The specified color count must be larger than one".into(),
            PastelError::GradientNumberOfColors => "The number of color arguments must be larger than one".into(),
            PastelError::DistinctColorCount => "The number of colors must be larger than one".into(),
            PastelError::DistinctColorFixedColorsCount => "The number of fixed colors must be smaller than the total number of colors".into(),
            PastelError::IoError(e) => format!("{}", e),
        }
    }
}

impl From<std::io::Error> for PastelError {
    fn from(e: std::io::Error) -> Self {
        if e.kind() == std::io::ErrorKind::BrokenPipe {
            PastelError::StdoutClosed
        } else {
            PastelError::IoError(e)
        }
    }
}

pub type Result<T> = std::result::Result<T, PastelError>;
