}

const TOOLS: &[Tool] = &[
    Tool { name: "gpick", command: "gpick", args: &["--pick", "--single", "--output"] },
    Tool { name: "xcolor", command: "xcolor", args: &["--format", "hex"] },
    Tool { name: "wcolor", command: "wcolor", args: &[] },
    Tool { name: "grabc", command: "grabc", args: &[] },
