    Tool { name: "chameleon", command: "chameleon", args: &[] },
    Tool { name: "kcolorchooser", command: "kcolorchooser", args: &["--print"] },
    Tool { name: "zenity", command: "zenity", args: &["--color-selection"] },
    Tool { name: "yad", command: "yad", args: &["--color"] },
    Tool { name: "hyprpicker", command: "hyprpicker", args: &[] },
