            "--dest",
            "org.freedesktop.portal.Desktop",
            "--object-path",
            "/org/freedesktop/portal/desktop",
            "--method",
            "org.freedesktop.portal.Screenshot.PickColor",
            "",
            "{}",
        ],
    },
    Tool { name: "macos", command: "osascript", args: &["-e", "choose color"] },
];

fn parse_tool_output(tool: &str, out: &str) -> Option<Color> {
    let out = out.trim();
    match tool {
        "gdbus" => {
            // (<{'color': <(0.1, 0.2, 0.3)>}>,)
            let start = out.find("(<(")? + 3;
            let end = out[start..].find(')')? + start;
            let nums: Vec<f64> = out[start..end]
                .split(',')
                .filter_map(|s| s.trim().parse::<f64>().ok())
                .collect();
            if nums.len() == 3 {
                Some(Color::from_rgb_float(nums[0], nums[1], nums[2]))
            } else {
                None
            }
        }
