        let old_color = self.colors[idx];
        let old_lab = self.labs[idx];
        let old_row: Vec<f64> = (0..n).map(|j| self.matrix[idx * n + j]).collect();
        let lab = color.to_lab();
        for j in 0..n {
            if j != idx {
                let d = dist(metric, &lab, &self.labs[j]);
                self.matrix[idx * n + j] = d;
                self.matrix[j * n + idx] = d;
            }
        }
        self.colors[idx] = color;
        self.labs[idx] = lab;
        (old_color, old_lab, old_row)
    }

    fn restore(&mut self, idx: usize, old: (Color, Lab, Vec<f64>)) {
        let n = self.n;
        self.colors[idx] = old.0;
        self.labs[idx] = old.1;
        for j in 0..n {
            self.matrix[idx * n + j] = old.2[j];
            self.matrix[j * n + idx] = old.2[j];
        }
    }
}

fn modify_color(rng: &mut Rng, color: &Color) -> Color {
    let mut lab = color.to_lab();
    let strategy = rng.below(3);
    let step = rng.range_f64(-8.0, 8.0);
    match strategy {
        0 => lab.l = (lab.l + step).clamp(0.0, 100.0),
        1 => lab.a = (lab.a + step * 1.5).clamp(-128.0, 128.0),
        _ => lab.b = (lab.b + step * 1.5).clamp(-128.0, 128.0),
    }
    Color::from_lab(lab.l, lab.a, lab.b, color.alpha)
}

fn hex(c: &Color) -> String {
    c.to_rgb_hex_string(false)
}

pub struct Callback<'a> {
    pub brush: Brush,
    pub out: &'a mut dyn Write,
}

fn print_iteration(cb: &mut Callback, iter: usize, result: &DistanceResult, temperature: f64, colors: &[Color]) {
    let mut line = format!(
        "[{:10}] D_mean = {:<6.2}; D_min = {:<6.2}; T = {:.6} ",
        iter, result.mean_closest_distance, result.min_closest_distance, temperature
    );
    for c in colors {
        let style = Style::new().foreground(&c.text_color()).on(c).bold(true).underline(true);
        line.push_str(&cb.brush.paint(&hex(c), &style));
        line.push(' ');
    }
    let _ = writeln!(cb.out, "{}", line);
}

fn annealing(
    rng: &mut Rng,
    state: &mut State,
    num_fixed: usize,
    params: &SimulationParameters,
    metric: DistanceMetric,
    callback: &mut Option<Callback>,
) {
    let n = state.n;
    let mut temperature = params.initial_temperature;
    let mut result = state.result();
    let score = |r: &DistanceResult| match params.opt_target {
        OptimizationTarget::Mean => r.mean_closest_distance,
        OptimizationTarget::Min => r.min_closest_distance,
    };
    for iter in 0..params.num_iterations {
        if iter % 5000 == 0 {
            if let Some(cb) = callback {
                print_iteration(cb, iter, &result, temperature, &state.colors);
            }
        }
        if iter % 1000 == 0 {
            temperature *= params.cooling_rate;
        }
        if num_fixed >= n {
            continue;
        }
        let idx = num_fixed + rng.below(n - num_fixed);
        let new_color = modify_color(rng, &state.colors[idx]);
        let old = state.update(idx, new_color, metric);
        let new_result = state.result();
        let s_old = score(&result);
        let s_new = score(&new_result);
        let accept = if s_new > s_old {
            true
        } else {
            let boltzmann = f64::exp(-(s_old - s_new) / temperature);
            rng.f64() <= boltzmann
        };
        if accept {
            result = new_result;
        } else {
            state.restore(idx, old);
        }
    }
}

pub fn distinct_colors(
    count: usize,
    metric: DistanceMetric,
    fixed_colors: Vec<Color>,
    callback: &mut Option<Callback>,
) -> (Vec<Color>, Vec<f64>) {
    let mut rng = Rng::new();
    let num_fixed = fixed_colors.len();
    let mut colors = fixed_colors;
    while colors.len() < count {
        colors.push(Color::from_rgb(rng.u8(), rng.u8(), rng.u8()));
    }
    let mut state = State::new(colors, metric);

    let p1 = SimulationParameters {
        initial_temperature: 3.0,
        cooling_rate: 0.95,
        num_iterations: 100_000,
        opt_target: OptimizationTarget::Mean,
    };
    annealing(&mut rng, &mut state, num_fixed, &p1, metric, callback);
    let p2 = SimulationParameters {
        initial_temperature: 0.5,
        cooling_rate: 0.98,
        num_iterations: 200_000,
        opt_target: OptimizationTarget::Min,
    };
    annealing(&mut rng, &mut state, num_fixed, &p2, metric, callback);

    // rearrange: keep first, then greedily pick the color maximizing the min distance to chosen
    let n = state.n;
    let mut order: Vec<usize> = vec![0];
    let mut remaining: Vec<usize> = (1..n).collect();
    while !remaining.is_empty() {
        let mut best_i = 0;
        let mut best_d = -1.0;
        for (k, &cand) in remaining.iter().enumerate() {
            let mut min_d = f64::MAX;
            for &c in &order {
                let d = state.matrix[cand * n + c];
                if d < min_d {
                    min_d = d;
                }
            }
            if min_d > best_d {
                best_d = min_d;
                best_i = k;
            }
        }
        order.push(remaining.remove(best_i));
    }
    let colors: Vec<Color> = order.iter().map(|&i| state.colors[i]).collect();
    let mut matrix = vec![0.0; n * n];
    for (a, &i) in order.iter().enumerate() {
        for (b, &j) in order.iter().enumerate() {
            matrix[a * n + b] = state.matrix[i * n + j];
        }
    }
    (colors, matrix)
}

/// Color used to visualize a distance in the distance matrix (yellow = close, dark blue = far).
fn scale_color(fraction: f64) -> Color {
    let f = fraction.clamp(0.0, 1.0);
    let p = f.powf(0.2925);
    let hue = 60.0 - 180.0 * p;
    // lightness as a piecewise-linear function of the fraction (empirically determined)
    const TABLE: &[(f64, f64)] = &[
        (0.0, 0.5),
        (0.0001, 0.494),
        (0.0004, 0.488),
        (0.0012, 0.484),
        (0.0057, 0.475),
        (0.0099, 0.469),
        (0.0198, 0.463),
        (0.0285, 0.459),
        (0.08, 0.443),
        (0.1192, 0.427),
        (0.1512, 0.412),
        (0.1818, 0.398),
        (0.2442, 0.376),
        (0.29, 0.361),
        (0.3952, 0.335),
        (0.5083, 0.310),
        (0.6117, 0.292),
        (0.7969, 0.263),
        (1.0, 0.235),
    ];
    let mut l = 0.235;
    for w in TABLE.windows(2) {
        let (f0, l0) = w[0];
        let (f1, l1) = w[1];
        if f >= f0 && f <= f1 {
            let t = if f1 > f0 { (f - f0) / (f1 - f0) } else { 0.0 };
            l = l0 + t * (l1 - l0);
            break;
        }
    }
    Color::from_hsl(hue, 1.0, l)
}

pub fn print_distance_matrix(cb: &mut Callback, colors: &[Color], matrix: &[f64]) {
    let n = colors.len();
    let mut out = String::new();
    out.push_str("\n\n        ");
    for c in colors {
        out.push_str(&cb.brush.paint(&hex(c), &Style::new().foreground(&c.text_color()).on(c)));
        out.push(' ');
    }
    out.push_str("\n\n");
    let mut dmin = f64::MAX;
    let mut dmax = f64::MIN;
    for i in 0..n {
        for j in 0..n {
            if i != j {
                let d = matrix[i * n + j];
                dmin = dmin.min(d);
                dmax = dmax.max(d);
            }
        }
    }
    for i in 0..n {
        let c = &colors[i];
        out.push_str(&cb.brush.paint(&hex(c), &Style::new().foreground(&c.text_color()).on(c)));
        out.push_str("  ");
        for j in 0..n {
            if i == j {
                out.push_str("       ");
            } else {
                let d = matrix[i * n + j];
                let fraction = if dmax > dmin { (d - dmin) / (dmax - dmin) } else { 0.0 };
                let bg = scale_color(fraction);
                let text = format!("{:6.2}", d);
                out.push_str(&cb.brush.paint(&text, &Style::new().foreground(&bg.text_color()).on(&bg)));
                out.push(' ');
            }
        }
        out.push('\n');
    }
    out.push_str("\n\n");
    let _ = write!(cb.out, "{}", out);
}
