use ansi::{Brush, Mode, Style};
use canvas::Canvas;
use color::{Color, ColorSpace, ColorblindnessType, DistanceMetric, Format};
use config::Config;
use error::{PastelError, Result};
use std::io::{self, BufRead, IsTerminal, Write};

// ---------------------------------------------------------------------------
// color input handling
// ---------------------------------------------------------------------------

fn parse_color_arg(s: &str) -> Result<Color> {
    parser::parse_color(s).ok_or_else(|| PastelError::ColorParseError(s.trim().to_string()))
}

fn number_arg(s: &str) -> Result<f64> {
    s.parse::<f64>().map_err(|_| PastelError::CouldNotParseNumber(s.to_string()))
}

fn usize_arg(s: &str) -> Result<usize> {
    s.parse::<usize>().map_err(|_| PastelError::CouldNotParseNumber(s.to_string()))
}

struct StdinColors {
    lines: Option<io::Lines<io::StdinLock<'static>>>,
}

impl StdinColors {
    fn new() -> StdinColors {
        StdinColors { lines: None }
    }
    fn next_line(&mut self) -> Option<io::Result<String>> {
        if self.lines.is_none() {
            let stdin: &'static io::Stdin = Box::leak(Box::new(io::stdin()));
            self.lines = Some(stdin.lock().lines());
        }
        self.lines.as_mut().unwrap().next()
    }
}

enum ColorSource {
    Args(Vec<String>, usize),
    Stdin,
}

/// Iterator over colors given as arguments or read from stdin.
struct ColorArgIterator<'a> {
    config: &'a Config,
    source: ColorSource,
    stdin: StdinColors,
    done: bool,
}

impl<'a> ColorArgIterator<'a> {
    fn new(config: &'a Config, args: Vec<String>) -> Result<ColorArgIterator<'a>> {
        if args.is_empty() {
            if io::stdin().is_terminal() {
                return Err(PastelError::ColorArgRequired);
            }
            Ok(ColorArgIterator { config, source: ColorSource::Stdin, stdin: StdinColors::new(), done: false })
        } else {
            Ok(ColorArgIterator { config, source: ColorSource::Args(args, 0), stdin: StdinColors::new(), done: false })
        }
    }

    fn color_from_stdin(&mut self) -> Result<Color> {
        match self.stdin.next_line() {
            Some(Ok(line)) => parse_color_arg(line.trim()),
            _ => Err(PastelError::CouldNotReadFromStdin),
        }
    }

    fn color_from_arg(&mut self, arg: &str) -> Result<Color> {
        if arg == "-" {
            self.color_from_stdin()
        } else if arg == "pick" {
            colorpicker::print_colorspectrum(self.config)?;
            colorpicker::run_external_colorpicker(self.config)
        } else {
            parse_color_arg(arg)
        }
    }
}

impl<'a> Iterator for ColorArgIterator<'a> {
    type Item = Result<Color>;
    fn next(&mut self) -> Option<Result<Color>> {
        if self.done {
            return None;
        }
        match &mut self.source {
            ColorSource::Args(args, idx) => {
                if *idx >= args.len() {
                    return None;
                }
                let arg = args[*idx].clone();
                *idx += 1;
                Some(self.color_from_arg(&arg))
            }
            ColorSource::Stdin => match self.stdin.next_line() {
                Some(Ok(line)) => Some(parse_color_arg(line.trim())),
                Some(Err(_)) => {
                    self.done = true;
                    Some(Err(PastelError::CouldNotReadFromStdin))
                }
                None => {
                    self.done = true;
                    None
                }
            },
        }
    }
}

// ---------------------------------------------------------------------------
// output
// ---------------------------------------------------------------------------

struct Output {
    out: io::Stdout,
    first_canvas: bool,
}

impl Output {
    fn new() -> Output {
        Output { out: io::stdout(), first_canvas: true }
    }

    fn write_line(&mut self, s: &str) -> Result<()> {
        let mut lock = self.out.lock();
        writeln!(lock, "{}", s)?;
        Ok(())
    }

    fn write_raw(&mut self, s: &str) -> Result<()> {
        let mut lock = self.out.lock();
        write!(lock, "{}", s)?;
        lock.flush()?;
        Ok(())
    }

    fn show_color(&mut self, config: &Config, color: &Color) -> Result<()> {
        if config.interactive_mode {
            self.show_color_tty(config, color)
        } else {
            self.write_line(&color.to_hsl_string(Format::NoSpaces))
        }
    }

    fn show_color_tty(&mut self, config: &Config, color: &Color) -> Result<()> {
        let checkerboard_size: usize = 16;
        let color_panel_size: usize = 12;
        let color_panel_position: usize = config.padding + (checkerboard_size - color_panel_size) / 2;
        let text_position_x: usize = checkerboard_size + 2 * config.padding;
        let text_position_y: usize = 0;

        let mut canvas = Canvas::new(checkerboard_size, 60, config.brush);
        canvas.draw_checkerboard(
            0,
            config.padding,
            checkerboard_size,
            checkerboard_size,
            &Color::graytone(0.71),
            &Color::graytone(0.94),
        );
        canvas.draw_rect(color_panel_position, color_panel_position, color_panel_size, color_panel_size, color);

        let rgba = color.to_rgba();
        let mut row = text_position_y;
        let named = named::NAMED_COLORS
            .iter()
            .find(|n| Color::from_rgb(n.rgb.0, n.rgb.1, n.rgb.2).to_rgba() == rgba)
            .map(|n| n.name);
        if let Some(name) = named {
            canvas.draw_text(row, text_position_x, &format!("Name: {}", name));
            row += 1;
        }
        canvas.draw_text(row, text_position_x, &format!("Hex: {}", color.to_rgb_hex_string(true)));
        row += 1;
        canvas.draw_text(row, text_position_x, &format!("RGB: {}", color.to_rgb_string(Format::Spaces)));
        row += 1;
        canvas.draw_text(row, text_position_x, &format!("HSL: {}", color.to_hsl_string(Format::Spaces)));
        row += 2;
        canvas.draw_text(row, text_position_x, "Most similar:");
        row += 1;

        // most similar named colors (CIEDE2000), excluding the exact color
        let mut similar: Vec<(f64, &named::NamedColor)> = named::NAMED_COLORS
            .iter()
            .map(|n| {
                let c = Color::from_rgb(n.rgb.0, n.rgb.1, n.rgb.2);
                (color.distance_delta_e_ciede2000(&c), n)
            })
            .collect();
        similar.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
        let mut shown = 0;
        for (_, n) in similar.iter().take(3) {
            let c = Color::from_rgb(n.rgb.0, n.rgb.1, n.rgb.2);
            if c.to_rgba() == rgba {
                continue;
            }
            canvas.draw_rect(2 * (row + shown), text_position_x + 1, 2, 5, &c);
            canvas.draw_text(row + shown, text_position_x + 7, n.name);
            shown += 1;
        }

        let mut lock = self.out.lock();
        if self.first_canvas {
            writeln!(lock)?;
            self.first_canvas = false;
        }
        canvas.print(&mut lock)?;
        writeln!(lock)?;
        Ok(())
    }
}

