fn mode_from_env() -> Result<Option<Mode>> {
    match std::env::var("PASTEL_COLOR_MODE").ok() {
        Some(mode) => match mode.as_str() {
            "24bit" | "truecolor" => Ok(Some(Mode::TrueColor)),
            "8bit" => Ok(Some(Mode::Ansi8Bit)),
            "off" => Ok(None),
            other => Err(PastelError::UnknownColorMode(other.to_string())),
        },
        None => {
            let colorterm = std::env::var("COLORTERM").unwrap_or_default();
            if colorterm == "truecolor" || colorterm == "24bit" {
                Ok(Some(Mode::TrueColor))
            } else {
                Ok(Some(Mode::Ansi8Bit))
            }
        }
    }
}

/// Brush for output written to stderr (verbose output, color picker spectrum).
pub fn stderr_brush() -> Result<Brush> {
    if io::stderr().is_terminal() {
        Ok(Brush::from_mode(mode_from_env()?))
    } else {
        Ok(Brush::from_mode(None))
    }
}

fn print_warning_8bit() {
    let header = "\x1b[38;5;226m[pastel warning]\x1b[0m";
    eprintln!("{}: Your terminal emulator does not appear to support 24-bit colors (this means that the COLORTERM environment variable is not set to 'truecolor' or '24bit'). pastel will fall back to 8-bit colors, but you will only be able to see rough approximations of the real colors.

To fix this, follow these steps:
  1. Run 'pastel colorcheck' to test if your terminal
     emulator does support 24-bit colors. If this is the
     case, set 'PASTEL_COLOR_MODE=24bit' to force 24-bit
     mode and to remove this warning. Alternatively, make
     sure that COLORTERM is properly set by your terminal
     emulator.
  2. If your terminal emulator does not support 24-bit
     colors, set 'PASTEL_COLOR_MODE=8bit' to remove this
     warning or try a different terminal emulator.

For more information, see https://gist.github.com/XVilka/8346728
", header);
}

