fn colorspace_arg(s: &str) -> ColorSpace {
    match s.to_ascii_lowercase().as_str() {
        "rgb" => ColorSpace::Rgb,
        "hsl" => ColorSpace::Hsl,
        "lch" => ColorSpace::LCh,
        "oklab" => ColorSpace::OkLab,
        _ => ColorSpace::Lab,
    }
}

fn sort_key(order: &str, c: &Color, rng: &mut rng::Rng) -> f64 {
    match order {
        "brightness" => c.brightness(),
        "luminance" => c.luminance(),
        "hue" => c.to_lch().h,
        "chroma" => c.to_lch().c,
        "random" => rng.f64(),
        _ => 0.0,
    }
}

fn run_command(parsed: &cli::ParsedCli, config: &Config, out: &mut Output) -> Result<()> {
    let m = &parsed.matches;
    match parsed.command.as_str() {
        "color" => {
            for c in ColorArgIterator::new(config, m.get_many("color"))? {
                out.show_color(config, &c?)?;
            }
        }
        "colorblind" => {
            let ty = match m.get("type").unwrap_or("").to_ascii_lowercase().as_str() {
                "prot" => ColorblindnessType::Protanopia,
                "deuter" => ColorblindnessType::Deuteranopia,
                _ => ColorblindnessType::Tritanopia,
            };
            for c in ColorArgIterator::new(config, m.get_many("color"))? {
                out.show_color(config, &c?.simulate_colorblindness(ty))?;
            }
        }
        "colorcheck" => cmd_colorcheck(config, out)?,
        "complement" => {
            for c in ColorArgIterator::new(config, m.get_many("color"))? {
                out.show_color(config, &c?.complementary())?;
            }
        }
        "darken" | "lighten" | "saturate" | "desaturate" => {
            let amount = number_arg(m.get("amount").unwrap_or(""))?;
            for c in ColorArgIterator::new(config, m.get_many("color"))? {
                let c = c?;
                let r = match parsed.command.as_str() {
                    "darken" => c.darken(amount),
                    "lighten" => c.lighten(amount),
                    "saturate" => c.saturate(amount),
                    _ => c.desaturate(amount),
                };
                out.show_color(config, &r)?;
            }
        }
        "rotate" => {
            let degrees = number_arg(m.get("degrees").unwrap_or(""))?;
            for c in ColorArgIterator::new(config, m.get_many("color"))? {
                out.show_color(config, &c?.rotate_hue(degrees))?;
            }
        }
        "to-gray" => {
            for c in ColorArgIterator::new(config, m.get_many("color"))? {
                out.show_color(config, &c?.to_gray())?;
            }
        }
        "textcolor" => {
            for c in ColorArgIterator::new(config, m.get_many("color"))? {
                out.show_color(config, &c?.text_color())?;
            }
        }
        "gray" => {
            let l = number_arg(m.get("lightness").unwrap_or(""))?;
            out.show_color(config, &Color::graytone(l))?;
        }
        "set" => {
            let property = m.get("property").unwrap_or("").to_ascii_lowercase();
            let value = number_arg(m.get("value").unwrap_or(""))?;
            for c in ColorArgIterator::new(config, m.get_many("color"))? {
                let c = c?;
                let r = match property.as_str() {
                    "lightness" => {
                        let l = c.to_lch();
                        Color::from_lch(value, l.c, l.h, l.alpha)
                    }
                    "hue" => {
                        let l = c.to_lch();
                        Color::from_lch(l.l, l.c, value, l.alpha)
                    }
                    "chroma" => {
                        let l = c.to_lch();
                        Color::from_lch(l.l, value, l.h, l.alpha)
                    }
                    "lab-a" => {
                        let l = c.to_lab();
                        Color::from_lab(l.l, value, l.b, l.alpha)
                    }
                    "lab-b" => {
                        let l = c.to_lab();
                        Color::from_lab(l.l, l.a, value, l.alpha)
                    }
                    "oklab-l" => {
                        let l = c.to_oklab();
                        Color::from_oklab(value, l.a, l.b, l.alpha)
                    }
                    "oklab-a" => {
                        let l = c.to_oklab();
                        Color::from_oklab(l.l, value, l.b, l.alpha)
                    }
                    "oklab-b" => {
                        let l = c.to_oklab();
                        Color::from_oklab(l.l, l.a, value, l.alpha)
                    }
                    "red" | "green" | "blue" => {
                        let rgba = c.to_rgba();
                        let v = color::f64_to_u8(color::clamp(0.0, 255.0, value));
                        match property.as_str() {
                            "red" => Color::from_rgba(v, rgba.g, rgba.b, c.alpha),
                            "green" => Color::from_rgba(rgba.r, v, rgba.b, c.alpha),
                            _ => Color::from_rgba(rgba.r, rgba.g, v, c.alpha),
                        }
                    }
                    "hsl-hue" => Color::from_hsla(value, c.saturation, c.lightness, c.alpha),
                    "hsl-saturation" => Color::from_hsla(c.hue, value, c.lightness, c.alpha),
                    "hsl-lightness" => Color::from_hsla(c.hue, c.saturation, value, c.alpha),
                    _ => Color::from_hsla(c.hue, c.saturation, c.lightness, value),
                };
                out.show_color(config, &r)?;
            }
        }
        "format" => cmd_format(m, config, out)?,
        "list" => cmd_list(m, config, out)?,
        "random" => cmd_random(m, config, out)?,
        "distinct" => cmd_distinct(m, config, out)?,
        "gradient" => cmd_gradient(m, config, out)?,
        "mix" => cmd_mix(m, config, out)?,
        "sort-by" => cmd_sort(m, config, out)?,
        "paint" => cmd_paint(m, config, out)?,
        "pick" => cmd_pick(m, config, out)?,
        _ => {}
    }
    Ok(())
}

fn cmd_colorcheck(config: &Config, out: &mut Output) -> Result<()> {
    fn panel(brush: Brush) -> Canvas {
        let mut canvas = Canvas::new(2 * 2 + 8, 30, brush);
        let colors = [Color::from_rgb(73, 39, 50), Color::from_rgb(16, 51, 30), Color::from_rgb(29, 54, 90)];
        for (i, c) in colors.iter().enumerate() {
            canvas.draw_rect(2, 2 + i * 10, 8, 8, c);
        }
        canvas
    }
    let _ = config;
    let mut lock = out.out.lock();
    writeln!(lock, "\n8-bit mode:")?;
    panel(Brush::from_mode(Some(Mode::Ansi8Bit))).print(&mut lock)?;
    writeln!(lock, "24-bit mode:")?;
    panel(Brush::from_mode(Some(Mode::TrueColor))).print(&mut lock)?;
    writeln!(
        lock,
        "If your terminal emulator supports 24-bit colors, you should see three square color panels in the lower row and the colors should look similar (but slightly different from) the colors in the top row panels.\nThe panels in the lower row should look like squares that are filled with a uniform color (no stripes or other artifacts).\n\nYou can also open https://github.com/sharkdp/pastel/blob/master/doc/colorcheck.md in a browser to compare how the output should look like.\n"
    )?;
    Ok(())
}

fn cmd_format(m: &cli::Matches, config: &Config, out: &mut Output) -> Result<()> {
    let ty = m.get("type").unwrap_or("hex").to_ascii_lowercase();
    for c in ColorArgIterator::new(config, m.get_many("color"))? {
        let c = c?;
        let text = match ty.as_str() {
            "rgb" => c.to_rgb_string(Format::Spaces),
            "rgb-float" => c.to_rgb_float_string(Format::Spaces),
            "rgb-r" => format!("{}", c.to_rgba().r),
            "rgb-g" => format!("{}", c.to_rgba().g),
            "rgb-b" => format!("{}", c.to_rgba().b),
            "hex" => c.to_rgb_hex_string(true),
            "hsl" => c.to_hsl_string(Format::Spaces),
            "hsl-hue" => format!("{:.0}", c.to_hsla().h),
            "hsl-saturation" => format!("{:.4}", c.to_hsla().s),
            "hsl-lightness" => format!("{:.4}", c.to_hsla().l),
            "hsv" => c.to_hsv_string(Format::Spaces),
            "hsv-hue" => format!("{:.0}", c.to_hsva().h),
            "hsv-saturation" => format!("{:.4}", c.to_hsva().s),
            "hsv-value" => format!("{:.4}", c.to_hsva().v),
            "lch" => c.to_lch_string(Format::Spaces),
            "lch-lightness" => format!("{:.2}", c.to_lch().l),
            "lch-chroma" => format!("{:.2}", c.to_lch().c),
            "lch-hue" => format!("{:.2}", c.to_lch().h),
            "oklch" => c.to_oklch_string(Format::Spaces),
            "oklch-lightness" => format!("{:.4}", c.to_oklch().l),
            "oklch-chroma" => format!("{:.4}", c.to_oklch().c),
            "oklch-hue" => format!("{:.4}", c.to_oklch().h),
            "lab" => c.to_lab_string(Format::Spaces),
            "lab-a" => format!("{:.2}", c.to_lab().a),
            "lab-b" => format!("{:.2}", c.to_lab().b),
            "oklab" => c.to_oklab_string(Format::Spaces),
            "oklab-l" => format!("{:.4}", c.to_oklab().l),
            "oklab-a" => format!("{:.4}", c.to_oklab().a),
            "oklab-b" => format!("{:.4}", c.to_oklab().b),
            "luminance" => format!("{:.3}", c.luminance()),
            "brightness" => format!("{:.3}", c.brightness()),
            "ansi-8bit" => format!("\\x1b[38;5;{}m", ansi::to_ansi_8bit(&c)),
            "ansi-24bit" => {
                let r = c.to_rgba();
                format!("\\x1b[38;2;{};{};{}m", r.r, r.g, r.b)
            }
            "ansi-8bit-value" => format!("{}", ansi::to_ansi_8bit(&c)),
            "ansi-8bit-escapecode" => {
                out.write_raw(&ansi::ansi_escape_8bit(&c))?;
                continue;
            }
            "ansi-24bit-escapecode" => {
                out.write_raw(&ansi::ansi_escape_24bit(&c))?;
                continue;
            }
            "cmyk" => c.to_cmyk_string(Format::Spaces),
            "name" => {
                let mut best: Option<(f64, &str)> = None;
                for n in named::NAMED_COLORS {
                    let nc = Color::from_rgb(n.rgb.0, n.rgb.1, n.rgb.2);
                    let d = c.distance_delta_e_ciede2000(&nc);
                    if best.map_or(true, |(bd, _)| d < bd) {
                        best = Some((d, n.name));
                    }
                }
                best.map(|(_, n)| n.to_string()).unwrap_or_default()
            }
            _ => c.to_rgb_hex_string(true),
        };
        out.write_line(&config.brush.paint(&text, &ansi::color_style(&c)))?;
    }
    Ok(())
}

fn cmd_list(m: &cli::Matches, config: &Config, out: &mut Output) -> Result<()> {
    let order = m.get("sort-order").unwrap_or("hue").to_string();
    let mut rng = rng::Rng::new();
    let mut colors: Vec<(&str, Color)> =
        named::NAMED_COLORS.iter().map(|n| (n.name, Color::from_rgb(n.rgb.0, n.rgb.1, n.rgb.2))).collect();
    let keys: Vec<f64> = colors.iter().map(|(_, c)| sort_key(&order, c, &mut rng)).collect();
    let mut idx: Vec<usize> = (0..colors.len()).collect();
    idx.sort_by(|&a, &b| keys[a].partial_cmp(&keys[b]).unwrap_or(std::cmp::Ordering::Equal));
    colors = idx.iter().map(|&i| colors[i]).collect();
    // remove duplicates (same RGB value), keeping the first occurrence
    let mut seen: Vec<color::RGBA<u8>> = Vec::new();
    colors.retain(|(_, c)| {
        let r = c.to_rgba();
        if seen.iter().any(|s| *s == r) {
            false
        } else {
            seen.push(r);
            true
        }
    });
    let mut s = String::new();
    for (name, c) in &colors {
        if config.interactive_mode {
            let text = format!(" {:24}", name);
            s.push_str(&config.brush.paint(&text, &ansi::color_style(c)));
            s.push('\n');
        } else {
            s.push_str(name);
            s.push('\n');
        }
    }
    out.write_raw(&s)?;
    Ok(())
}

fn cmd_random(m: &cli::Matches, config: &Config, out: &mut Output) -> Result<()> {
    let count = usize_arg(m.get("number").unwrap_or("10"))?;
    let strategy = m.get("strategy").unwrap_or("vivid").to_string();
    let mut rng = rng::Rng::new();
    for _ in 0..count {
        let c = match strategy.as_str() {
            "rgb" => Color::from_rgb(rng.u8(), rng.u8(), rng.u8()),
            "gray" => Color::graytone(rng.f64()),
            "lch_hue" => Color::from_lch(70.0, 35.0, rng.range_f64(0.0, 360.0), 1.0),
            _ => Color::from_hsl(rng.range_f64(0.0, 360.0), rng.range_f64(0.2, 0.8), rng.range_f64(0.3, 0.7)),
        };
        out.show_color(config, &c)?;
    }
    Ok(())
}

fn cmd_distinct(m: &cli::Matches, config: &Config, out: &mut Output) -> Result<()> {
    let count = usize_arg(m.get("count").unwrap_or("10"))?;
    let metric = if m.get("metric") == Some("CIEDE2000") { DistanceMetric::CIEDE2000 } else { DistanceMetric::CIE76 };
    let verbose = m.is_present("verbose");
    let stderr_brush = stderr_brush()?;
    if count < 2 {
        return Err(PastelError::DistinctColorCount);
    }
    let fixed: Vec<Color> = if m.get_many("color").is_empty() {
        Vec::new()
    } else {
        ColorArgIterator::new(config, m.get_many("color"))?.collect::<Result<Vec<Color>>>()?
    };
    if fixed.len() >= count {
        return Err(PastelError::DistinctColorFixedColorsCount);
    }
    let stderr = io::stderr();
    let mut lock = stderr.lock();
    let mut callback = if verbose { Some(distinct::Callback { brush: stderr_brush, out: &mut lock }) } else { None };
    let (colors, matrix) = distinct::distinct_colors(count, metric, fixed, &mut callback);
    if let Some(cb) = &mut callback {
        distinct::print_distance_matrix(cb, &colors, &matrix);
    }
    drop(callback);
    for c in &colors {
        out.show_color(config, c)?;
    }
    Ok(())
}

fn cmd_gradient(m: &cli::Matches, config: &Config, out: &mut Output) -> Result<()> {
    let count = usize_arg(m.get("number").unwrap_or("10"))?;
    let space = colorspace_arg(m.get("colorspace").unwrap_or("Lab"));
    let colors: Vec<Color> = ColorArgIterator::new(config, m.get_many("color"))?.collect::<Result<Vec<Color>>>()?;
    if count < 2 {
        return Err(PastelError::GradientColorCount);
    }
    if colors.len() < 2 {
        return Err(PastelError::GradientNumberOfColors);
    }
    let n_stops = colors.len();
    for i in 0..count {
        let t = i as f64 / (count - 1) as f64;
        // find segment
        let seg = (n_stops - 1) as f64;
        let pos = t * seg;
        let mut k = pos.floor() as usize;
        if k >= n_stops - 1 {
            k = n_stops - 2;
        }
        let frac = pos - k as f64;
        let c = colors[k].mix(&colors[k + 1], frac, space);
        out.show_color(config, &c)?;
    }
    Ok(())
}

fn cmd_mix(m: &cli::Matches, config: &Config, out: &mut Output) -> Result<()> {
    let space = colorspace_arg(m.get("colorspace").unwrap_or("Lab"));
    let fraction = number_arg(m.get("fraction").unwrap_or("0.5"))?;
    let base_arg = m.get("base").unwrap_or("").to_string();
    let mut base_iter = ColorArgIterator::new(config, vec![base_arg])?;
    let base = base_iter.next().unwrap()?;
    for c in ColorArgIterator::new(config, m.get_many("color"))? {
        let c = c?;
        out.show_color(config, &c.mix(&base, fraction, space))?;
    }
    Ok(())
}

fn cmd_sort(m: &cli::Matches, config: &Config, out: &mut Output) -> Result<()> {
    let order = m.get("sort-order").unwrap_or("hue").to_string();
    let reverse = m.is_present("reverse");
    let unique = m.is_present("unique");
    let mut colors: Vec<Color> = ColorArgIterator::new(config, m.get_many("color"))?.collect::<Result<Vec<Color>>>()?;
    let mut rng = rng::Rng::new();
    let keys: Vec<f64> = colors.iter().map(|c| sort_key(&order, c, &mut rng)).collect();
    let mut idx: Vec<usize> = (0..colors.len()).collect();
    idx.sort_by(|&a, &b| keys[a].partial_cmp(&keys[b]).unwrap_or(std::cmp::Ordering::Equal));
    colors = idx.iter().map(|&i| colors[i]).collect();
    if unique {
        let mut seen: Vec<color::RGBA<u8>> = Vec::new();
        colors.retain(|c| {
            let mut r = c.to_rgba();
            r.alpha = 1.0;
            if seen.iter().any(|s| *s == r) {
                false
            } else {
                seen.push(r);
                true
            }
        });
    }
    if reverse {
        colors.reverse();
    }
    for c in &colors {
        out.show_color(config, c)?;
    }
    Ok(())
}

fn cmd_paint(m: &cli::Matches, config: &Config, out: &mut Output) -> Result<()> {
    let color_arg = m.get("color").unwrap_or("").to_string();
    let mut it = ColorArgIterator::new(config, vec![color_arg])?;
    let fg = it.next().unwrap()?;
    let bg = match m.get("on") {
        Some(s) => Some(parse_color_arg(s)?),
        None => None,
    };
    let texts = m.get_many("text");
    let text = if texts.is_empty() {
        let mut s = String::new();
        io::stdin().lock().read_to_string(&mut s)?;
        s
    } else {
        texts.join(" ")
    };
    let mut style = Style::new().foreground(&fg);
    if let Some(bg) = &bg {
        style = style.on(bg);
    }
    style = style.bold(m.is_present("bold")).italic(m.is_present("italic")).underline(m.is_present("underline"));
    let painted = config.brush.paint(&text, &style);
    if m.is_present("no-newline") {
        out.write_raw(&painted)?;
    } else {
        out.write_line(&painted)?;
    }
    Ok(())
}

fn cmd_pick(m: &cli::Matches, config: &Config, out: &mut Output) -> Result<()> {
    let count = usize_arg(m.get("count").unwrap_or("1"))?;
    colorpicker::print_colorspectrum(config)?;
    for _ in 0..count {
        let c = colorpicker::run_external_colorpicker(config)?;
        out.show_color(config, &c)?;
    }
    Ok(())
}

