fn print_error(interactive: bool, msg: &str) {
    if interactive {
        eprintln!("\x1b[38;5;196m[pastel error]\x1b[0m: {}", msg);
    } else {
        eprintln!("[pastel error]: {}", msg);
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let bin = std::path::Path::new(&args[0])
        .file_name()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| "pastel".to_string());
    let ctx = cli::HelpCtx { bin, term_w: term::help_width() };
    let parsed = match cli::parse(&ctx, &args[1..]) {
        Ok(p) => p,
        Err(cli::Exit::Stdout(s)) => {
            let _ = io::stdout().write_all(s.as_bytes());
            let _ = io::stdout().flush();
            std::process::exit(0);
        }
        Err(cli::Exit::Stderr(s)) => {
            let _ = io::stderr().write_all(s.as_bytes());
            std::process::exit(2);
        }
    };

    let interactive_mode = io::stdout().is_terminal();

    // determine color mode
    let mode_result: Result<Option<Mode>> = if parsed.force_color {
        Ok(Some(Mode::TrueColor))
    } else {
        match parsed.color_mode.as_deref() {
            Some("24bit") => Ok(Some(Mode::TrueColor)),
            Some("8bit") => Ok(Some(Mode::Ansi8Bit)),
            Some("off") => Ok(None),
            _ => {
                if interactive_mode {
                    match std::env::var("PASTEL_COLOR_MODE").ok() {
                        Some(mode) => match mode.as_str() {
                            "24bit" | "truecolor" => Ok(Some(Mode::TrueColor)),
                            "8bit" => Ok(Some(Mode::Ansi8Bit)),
                            "off" => Ok(None),
                            other => Err(PastelError::UnknownColorMode(other.to_string())),
                        },
                        None => {
                            let colorterm = std::env::var("COLORTERM").unwrap_or_default();
                            if colorterm == "truecolor" || colorterm == "24bit" {
                                Ok(Some(Mode::TrueColor))
                            } else {
                                print_warning_8bit();
                                Ok(Some(Mode::Ansi8Bit))
                            }
                        }
                    }
                } else {
