struct Pending<'a> {
    def: &'a ArgDef,
    values: Vec<String>,
}

/// Shared parsing state for one command level.
struct State<'a> {
    m: Matches,
    used_options: Vec<String>,
    used_positionals: Vec<String>,
    pending: Option<Pending<'a>>,
    pos_index: usize,
    after_dd: bool,
}

impl<'a> State<'a> {
    fn new() -> State<'a> {
        State {
            m: Matches::default(),
            used_options: Vec::new(),
            used_positionals: Vec::new(),
            pending: None,
            pos_index: 0,
            after_dd: false,
        }
    }

    /// Resolve the pending argument (validate and store its values).
    fn resolve(&mut self, plain_usage: &str) -> Result<(), Exit> {
        if let Some(p) = self.pending.take() {
            if p.def.positional {
                for v in &p.values {
                    let v = validate_value(p.def, v)?;
                    self.m.values.entry(p.def.id.to_string()).or_default().push(v);
                }
                if !self.used_positionals.iter().any(|u| u == p.def.id) {
                    self.used_positionals.push(p.def.id.to_string());
                }
            } else {
                if p.values.is_empty() {
                    return Err(value_required_error(p.def));
                }
                if self.m.values.contains_key(p.def.id) {
                    return Err(err_with_usage(
                        &format!("the argument '{}' cannot be used multiple times", p.def.display()),
                        None,
                        Some(plain_usage.to_string()),
                    ));
                }
                let v = validate_value(p.def, &p.values[0])?;
                self.m.values.insert(p.def.id.to_string(), vec![v]);
                self.used_options.push(p.def.id.to_string());
            }
        }
        Ok(())
    }

    fn set_flag(&mut self, def: &ArgDef, plain_usage: &str) -> Result<(), Exit> {
        if self.m.flags.contains_key(def.id) {
            return Err(err_with_usage(
                &format!("the argument '{}' cannot be used multiple times", def.display()),
                None,
                Some(plain_usage.to_string()),
            ));
        }
        self.m.flags.insert(def.id.to_string(), true);
        self.used_options.push(def.id.to_string());
        Ok(())
    }

    /// Is there a pending option waiting for its value?
    fn option_wants_value(&self) -> bool {
        matches!(&self.pending, Some(p) if !p.def.positional && p.values.is_empty())
    }
}

fn split_long(a: &str) -> (&str, Option<String>) {
    match a[2..].find('=') {
        Some(p) => (&a[2..2 + p], Some(a[3 + p..].to_string())),
        None => (&a[2..], None),
    }
}

