    let mut m = st.m;
    for a in &cmd.args {
        if let Some(d) = a.default {
            if a.takes_value() && !m.values.contains_key(a.id) {
                m.values.insert(a.id.to_string(), vec![d.to_string()]);
            }
        }
    }
    Ok(m)
}
