new_code = r'''fn is_flag_like(a: &str) -> bool {
    a.starts_with('-') && a.len() > 1
}

struct Pending<'a> {
    def: &'a ArgDef,
    values: Vec<String>,
}

/// Shared parsing state for one command level.
struct State<'a> {
    m: Matches,
    used_options: Vec<String>,
    used_positionals: Vec<String>,
    pending: Option<Pending<'a>>,
    pos_index: usize,
    after_dd: bool,
}

impl<'a> State<'a> {
    fn new() -> State<'a> {
        State {
            m: Matches::default(),
            used_options: Vec::new(),
            used_positionals: Vec::new(),
            pending: None,
            pos_index: 0,
            after_dd: false,
        }
    }

    /// Resolve the pending argument (validate and store its values).
    fn resolve(&mut self, plain_usage: &str) -> Result<(), Exit> {
        if let Some(p) = self.pending.take() {
            if p.def.positional {
                for v in &p.values {
                    let v = validate_value(p.def, v)?;
                    self.m.values.entry(p.def.id.to_string()).or_default().push(v);
                }
                if !self.used_positionals.iter().any(|u| u == p.def.id) {
                    self.used_positionals.push(p.def.id.to_string());
                }
            } else {
                if p.values.is_empty() {
                    return Err(value_required_error(p.def));
                }
                if self.m.values.contains_key(p.def.id) {
                    return Err(err_with_usage(
                        &format!("the argument '{}' cannot be used multiple times", p.def.display()),
                        None,
                        Some(plain_usage.to_string()),
                    ));
                }
                let v = validate_value(p.def, &p.values[0])?;
                self.m.values.insert(p.def.id.to_string(), vec![v]);
                self.used_options.push(p.def.id.to_string());
            }
        }
        Ok(())
    }

    fn set_flag(&mut self, def: &ArgDef, plain_usage: &str) -> Result<(), Exit> {
        if self.m.flags.contains_key(def.id) {
            return Err(err_with_usage(
                &format!("the argument '{}' cannot be used multiple times", def.display()),
                None,
                Some(plain_usage.to_string()),
            ));
        }
        self.m.flags.insert(def.id.to_string(), true);
        self.used_options.push(def.id.to_string());
        Ok(())
    }

    /// Is there a pending option waiting for its value?
    fn option_wants_value(&self) -> bool {
        matches!(&self.pending, Some(p) if !p.def.positional && p.values.is_empty())
    }
}

fn split_long(a: &str) -> (&str, Option<String>) {
    match a[2..].find('=') {
        Some(p) => (&a[2..2 + p], Some(a[3 + p..].to_string())),
        None => (&a[2..], None),
    }
}

/// Parse the full command line. `args` excludes the binary name.
pub fn parse(ctx: &HelpCtx, args: &[String]) -> Result<ParsedCli, Exit> {
    let opts = main_options();
    let plain = usage_main_plain(ctx);
    let mut st: State = State::new();
    let mut i = 0;

    while i < args.len() {
        let a = &args[i];
        if !st.after_dd && a == "--" {
            st.after_dd = true;
            i += 1;
            continue;
        }
        if !st.after_dd && a.starts_with("--") {
            let (name, inline) = split_long(a);
            let def = opts.iter().find(|o| o.long == Some(name));
            match def {
                None => {
                    let longs: Vec<&str> = opts.iter().filter_map(|o| o.long).collect();
                    let sugg = did_you_mean(name, longs.iter().copied());
                    let display = format!("--{}", name);
                    let _ = st.resolve(&plain);
                    if let Some(best) = sugg.last() {
                        let d = opts.iter().find(|o| o.long == Some(best.as_str())).unwrap();
                        let u = used_plus(&st.used_options, d.id);
                        return Err(err_with_usage(
                            &format!("unexpected argument '{}' found", display),
                            Some(format!("  tip: a similar argument exists: '--{}'", best)),
                            Some(usage_main_smart(ctx, &u)),
                        ));
                    }
                    let usage = if st.used_options.is_empty() { plain.clone() } else { usage_main_smart(ctx, &st.used_options) };
                    return Err(err_with_usage(&format!("unexpected argument '{}' found", display), None, Some(usage)));
                }
                Some(def) => {
                    st.resolve(&plain)?;
                    if def.takes_value() {
                        st.pending = Some(Pending { def, values: inline.into_iter().collect() });
                    } else {
                        if let Some(v) = inline {
                            return Err(err_with_usage(
                                &format!("unexpected value '{}' for '{}' found; no more were expected", v, def.display()),
                                None,
                                Some(usage_main_smart(ctx, &used_plus(&st.used_options, def.id))),
                            ));
                        }
                        match def.id {
                            "help" => return Err(Exit::Stdout(render_main_help(ctx))),
                            "version" => return Err(Exit::Stdout(format!("pastel {}\n", VERSION))),
                            _ => st.set_flag(def, &plain)?,
                        }
                    }
                }
            }
            i += 1;
            continue;
        }
        if !st.after_dd && is_flag_like(a) {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut k = 0;
            while k < chars.len() {
                let c = chars[k];
                let def = opts.iter().find(|o| o.short == Some(c));
                match def {
                    None => {
                        return Err(err_with_usage(
                            &format!("unexpected argument '-{}' found", c),
                            None,
                            Some(plain.clone()),
                        ));
                    }
                    Some(def) => {
                        st.resolve(&plain)?;
                        if def.takes_value() {
                            let rest: String = chars[k + 1..].iter().collect();
                            let values = if rest.is_empty() {
                                Vec::new()
                            } else {
                                vec![rest.strip_prefix('=').unwrap_or(&rest).to_string()]
                            };
                            st.pending = Some(Pending { def, values });
                            k = chars.len();
                        } else {
                            match def.id {
                                "help" => return Err(Exit::Stdout(render_main_help(ctx))),
                                "version" => return Err(Exit::Stdout(format!("pastel {}\n", VERSION))),
                                _ => st.set_flag(def, &plain)?,
                            }
                            k += 1;
                        }
                    }
                }
            }
            i += 1;
            continue;
        }
        // a value
        if st.option_wants_value() && !st.after_dd {
            st.pending.as_mut().unwrap().values.push(a.clone());
            i += 1;
            continue;
        }
        // subcommand
        if a == "help" && !st.after_dd {
            st.resolve(&plain)?;
            return parse_help_subcommand(ctx, &args[i + 1..]);
        }
        match find_command(a) {
            Some(cmd) => {
                if st.after_dd {
                    let _ = st.resolve(&plain);
                    return Err(err_with_usage(
                        &format!("unexpected argument '{}' found", a),
                        Some(format!("  tip: subcommand '{}' exists; to use it, remove the '--' before it", a)),
                        Some(plain.clone()),
                    ));
                }
                st.resolve(&plain)?;
                let matches = parse_subcommand(ctx, &cmd, &args[i + 1..])?;
                return Ok(ParsedCli {
                    color_picker: st.m.get("color-picker").map(|s| s.to_string()),
                    force_color: st.m.is_present("force-color"),
                    color_mode: st.m.get("color-mode").map(|s| s.to_string()),
                    command: cmd.name.to_string(),
                    matches,
                });
            }
            None => {
                let _ = st.resolve(&plain);
                if a == "help" {
                    return Err(err_with_usage(
                        "unexpected argument 'help' found",
                        Some("  tip: subcommand 'help' exists; to use it, remove the '--' before it".to_string()),
                        Some(plain.clone()),
                    ));
                }
                return Err(err_with_usage(
                    &format!("unrecognized subcommand '{}'", a),
                    subcommand_tip(a),
                    Some(plain.clone()),
                ));
            }
        }
    }
    st.resolve(&plain)?;
    if st.used_options.is_empty() {
        return Err(Exit::Stderr(render_main_help(ctx)));
    }
    let names = all_subcommand_names();
    Err(err_with_usage(
        &format!("'{}' requires a subcommand but one was not provided\n  [subcommands: {}]", ctx.bin, names.join(", ")),
        None,
        Some(plain),
    ))
}

fn used_plus(used: &[String], id: &str) -> Vec<String> {
    let mut u = used.to_vec();
    if !u.iter().any(|x| x == id) {
        u.push(id.to_string());
    }
    u
}

fn parse_help_subcommand(ctx: &HelpCtx, rest: &[String]) -> Result<ParsedCli, Exit> {
    if rest.is_empty() {
        return Err(Exit::Stdout(render_main_help(ctx)));
    }
    let name = &rest[0];
    if name == "help" {
        if rest.len() > 1 {
            return Err(Exit::Stderr(format!(
                "error: unrecognized subcommand '{}'\n\nUsage: {} help [COMMAND]...\n",
                rest[1], ctx.bin
            )));
        }
        return Err(Exit::Stdout(render_help_subcommand_help(ctx)));
    }
    match find_command(name) {
        Some(cmd) => {
            if rest.len() > 1 {
                return Err(err_with_usage(
                    &format!("unrecognized subcommand '{}'", rest[1]),
                    None,
                    Some(usage_plain(ctx, &cmd)),
                ));
            }
            Err(Exit::Stdout(render_subcommand_help(ctx, &cmd, true)))
        }
        None => Err(err_with_usage(
            &format!("unrecognized subcommand '{}'", name),
            None,
            Some(usage_main_plain(ctx)),
        )),
    }
}

fn parse_subcommand(ctx: &HelpCtx, cmd: &CmdDef, args: &[String]) -> Result<Matches, Exit> {
    let positionals: Vec<&ArgDef> = cmd.args.iter().filter(|a| a.positional).collect();
    let has_positionals = !positionals.is_empty();
    let plain = usage_plain(ctx, cmd);
    let mut st: State = State::new();
    let mut i = 0;

    let help_usage = |st: &State| {
        let s = usage_smart(ctx, cmd, &st.used_options, &st.used_positionals);
        s.replacen(&format!("{} {}", ctx.bin, cmd.name), &format!("{} {} --help", ctx.bin, cmd.name), 1)
    };

    while i < args.len() {
        let a = &args[i];
        if !st.after_dd && a == "--" {
            st.after_dd = true;
            i += 1;
            continue;
        }
        if !st.after_dd && a.starts_with("--") && a.len() > 2 {
            let (name, inline) = split_long(a);
            let def = cmd.args.iter().find(|o| !o.positional && o.long == Some(name));
            if name != "help" && def.is_none() {
                let _ = st.resolve(&plain);
                let mut longs: Vec<&str> = cmd.args.iter().filter_map(|o| o.long).collect();
                longs.push("help");
                let sugg = did_you_mean(name, longs.iter().copied());
                let display = format!("--{}", name);
                if let Some(best) = sugg.last() {
                    let usage = if best == "help" {
                        help_usage(&st)
                    } else {
                        let d = cmd.args.iter().find(|o| o.long == Some(best.as_str())).unwrap();
                        usage_smart(ctx, cmd, &used_plus(&st.used_options, d.id), &st.used_positionals)
                    };
                    return Err(err_with_usage(
                        &format!("unexpected argument '{}' found", display),
                        Some(format!("  tip: a similar argument exists: '--{}'", best)),
                        Some(usage),
                    ));
                }
                let tip = if has_positionals {
                    Some(format!("  tip: to pass '{}' as a value, use '-- {}'", display, display))
                } else {
                    None
                };
                let usage = if st.used_options.is_empty() && st.used_positionals.is_empty() {
                    plain.clone()
                } else {
                    usage_smart(ctx, cmd, &st.used_options, &st.used_positionals)
                };
                return Err(err_with_usage(&format!("unexpected argument '{}' found", display), tip, Some(usage)));
            }
            st.resolve(&plain)?;
            if name == "help" {
                if let Some(v) = inline {
                    return Err(err_with_usage(
                        &format!("unexpected value '{}' for '--help' found; no more were expected", v),
                        None,
                        Some(help_usage(&st)),
                    ));
                }
                return Err(Exit::Stdout(render_subcommand_help(ctx, cmd, true)));
            }
            let def = def.unwrap();
            if def.takes_value() {
                st.pending = Some(Pending { def, values: inline.into_iter().collect() });
            } else {
                if let Some(v) = inline {
                    let u = used_plus(&st.used_options, def.id);
                    return Err(err_with_usage(
                        &format!("unexpected value '{}' for '{}' found; no more were expected", v, def.display()),
                        None,
                        Some(usage_smart(ctx, cmd, &u, &st.used_positionals)),
                    ));
                }
                st.set_flag(def, &plain)?;
            }
            i += 1;
            continue;
        }
        if !st.after_dd && is_flag_like(a) {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut k = 0;
            while k < chars.len() {
                let c = chars[k];
                let def = cmd.args.iter().find(|o| !o.positional && o.short == Some(c));
                if c != 'h' && def.is_none() {
                    let display = format!("-{}", c);
                    let tip = if has_positionals {
                        Some(format!("  tip: to pass '{}' as a value, use '-- {}'", display, display))
                    } else {
                        None
                    };
                    return Err(err_with_usage(&format!("unexpected argument '{}' found", display), tip, Some(plain.clone())));
                }
                st.resolve(&plain)?;
                if c == 'h' {
                    return Err(Exit::Stdout(render_subcommand_help(ctx, cmd, false)));
                }
                let def = def.unwrap();
                if def.takes_value() {
                    let rest: String = chars[k + 1..].iter().collect();
                    let values = if rest.is_empty() {
                        Vec::new()
                    } else {
                        vec![rest.strip_prefix('=').unwrap_or(&rest).to_string()]
                    };
                    st.pending = Some(Pending { def, values });
                    k = chars.len();
                } else {
                    st.set_flag(def, &plain)?;
                    k += 1;
                }
            }
            i += 1;
            continue;
        }
        // a value
        if st.option_wants_value() && !st.after_dd {
            st.pending.as_mut().unwrap().values.push(a.clone());
            i += 1;
            continue;
        }
        // positional: append to pending multi-positional, or start a new one
        let appended = match &mut st.pending {
            Some(p) if p.def.positional && p.def.multiple => {
                p.values.push(a.clone());
                true
            }
            _ => false,
        };
        if !appended {
            if st.pos_index >= positionals.len() {
                let _ = st.resolve(&plain);
                return Err(err_with_usage(&format!("unexpected argument '{}' found", a), None, Some(plain.clone())));
            }
            st.resolve(&plain)?;
            let def = positionals[st.pos_index];
            st.pending = Some(Pending { def, values: vec![a.clone()] });
            st.pos_index += 1;
        }
        i += 1;
    }
    st.resolve(&plain)?;
    // required check
    let missing: Vec<String> = positionals
        .iter()
        .filter(|p| p.required && !st.m.values.contains_key(p.id))
        .map(|p| p.display())
        .collect();
    if !missing.is_empty() {
        let mut msg = String::from("the following required arguments were not provided:");
        for mi in &missing {
            msg.push_str(&format!("\n  {}", mi));
        }
        let usage = usage_smart(ctx, cmd, &st.used_options, &st.used_positionals);
        return Err(err_with_usage(&msg, None, Some(usage)));
    }
    // defaults
    let mut m = st.m;
    for a in &cmd.args {
        if let Some(d) = a.default {
            if a.takes_value() && !m.values.contains_key(a.id) {
                m.values.insert(a.id.to_string(), vec![d.to_string()]);
            }
        }
    }
    Ok(m)
}
